export const TOPICS_B = [
  { id: 'b001', cat: 'Духовен живот', title: 'Иисусовата молитва', text: 'Иисусовата молитва гласи: „Господи Иисусе Христе, Сине Божий, помилуй ме, грешния“. Тя съединява изповедта на вярата в Христос като Бог и Спасител с покаянието на човека, който се знае за немощен. Отците съветват да се казва бавно, с внимание към всяка дума, без да се търсят особени преживявания или образи. Може да се казва сутрин по броеница, но и през деня – в колата, по време на загрявка, преди тежък разговор. Ключът е постоянството и смирението: по-добре десет внимателни молитви, отколкото сто разсеяни.', read: 'Лука 18:13; „Откровените разкази на един странник пред неговия духовен отец“' },
  { id: 'b002', cat: 'Светите отци и светии', title: 'Свети Антоний Велики', text: 'Свети Антоний (III–IV в.) е наричан баща на монашеството. Като млад чул в храма думите на Христос: „Ако искаш да бъдеш съвършен, иди, продай имота си и го раздай на бедните“, и ги приел буквално. Десетилетия живял в египетската пустиня в молитва, труд и борба с изкушенията, които по-късно описвал на учениците си. Учел, че животът и смъртта ни зависят от ближния: ако спечелим брата, печелим Бога. Житието му, написано от св. Атанасий Велики, вдъхновило хиляди хора да тръгнат по пътя на подвига.', read: 'Мат. 19:21; св. Атанасий Велики, „Житие на св. Антоний Велики“' },
  { id: 'b003', cat: 'Църковна история', title: 'Петдесетница и първата Църква', text: 'На петдесетия ден след Възкресението Светият Дух слязъл над апостолите в Йерусалим във вид на огнени езици. Апостол Петър проповядвал и около три хиляди души приели кръщение – това е рожденият ден на Църквата. Първите християни пребъдвали в учението на апостолите, в общението, в преломяването на хляба и в молитвите. Те споделяли имуществото си и се грижели един за друг така, че нямало нуждаещ се сред тях. Тази картина остава образец за всяка енория и днес: Евхаристия, учение, молитва и действена любов.', read: 'Деян. 2:1–47; Деян. 4:32–35' },
  { id: 'b004', cat: 'Християнски живот', title: 'Трудът като служение', text: 'Още в рая Бог поставил човека „да обработва и пази“ градината, тоест трудът не е проклятие, а призвание. След грехопадението той става тежък и свързан с пот, но чрез Христос отново може да бъде принесен на Бога. Апостол Павел работел с ръцете си и казвал: „Който не иска да работи, нека и не яде“. Християнинът работи честно, не краде време и качество, и вижда в работата си служение на ближните. Добре е да започваш деня или тренировката с кратка молитва и да посвещаваш на Бога плодовете на усилията си.', read: 'Бит. 2:15; 2 Сол. 3:10–12; Кол. 3:23' },
  { id: 'b005', cat: 'Духовен живот', title: 'Какво е молитвата', text: 'Молитвата е разговор с живия Бог, а не изпълнение на задължение или магическа формула. Светите отци я наричат „дихание на душата“: както тялото без въздух умира, така и душата без молитва изсъхва. Тя включва славословие, благодарност, покаяние и прошение за себе си и другите. Не е нужно красноречие – Бог гледа сърцето, а не броя на думите. Започни с малко, но всеки ден, и пази в молитвата искреност: кажи на Бога точно това, което е в теб.', read: 'Мат. 6:5–13; св. Теофан Затворник, „Що е духовен живот и как да се настроим за него“' },
  { id: 'b006', cat: 'Светите отци и светии', title: 'Св. Игнатий Богоносец', text: 'Свети Игнатий е бил епископ на Антиохия в края на I и началото на II век и според преданието ученик на апостолите. Арестуван заради Христос, той бил отведен в Рим, за да бъде хвърлен на зверовете. По пътя написал седем послания до различни църкви, в които говори за единството около епископа и Евхаристията. Той нарича Причастието „лекарство за безсмъртие“ и моли християните в Рим да не му пречат да стане „пшеница Божия“. Посланията му показват, че още най-ранната Църква е евхаристийна и йерархична.', read: 'Св. Игнатий Богоносец, „Послание до римляните“; „Послание до ефесяни“' },
  { id: 'b007', cat: 'Църковна история', title: 'Апостол Павел и мисията', text: 'Савел бил ревностен гонител на християните, докато възкръсналият Христос не го срещнал на пътя за Дамаск. Обърнат, той станал апостол на езичниците и предприел няколко мисионерски пътувания из Мала Азия, Македония и Гърция. Основавал общности в градове като Филипи, Солун и Коринт и им пишел послания, които днес са част от Новия Завет. Претърпял бой, корабокрушения, затвор и накрая мъченическа смърт в Рим. Животът му показва, че никой не е твърде далеч от Бога и че благодатта прави от гонителя проповедник.', read: 'Деян. 9:1–22; 2 Кор. 11:23–33' },
  { id: 'b008', cat: 'Християнски живот', title: 'Парите в живота ни', text: 'Парите сами по себе си не са зло – Писанието казва, че „коренът на всички злини е сребролюбието“, а не самите пари. Те са средство, за което ще дадем отговор: как сме ги спечелили и как сме ги употребили. Християнинът се грижи за семейството си, но не поставя сигурността си в сметката, а в Бога. Добре е да отделяш редовна част от доходите си за Църквата и нуждаещите се, дори когато е малко. Питай се често: аз ли владея парите, или те мен?', read: '1 Тим. 6:6–10; Лука 12:15–21' },
  { id: 'b009', cat: 'Духовен живот', title: 'Утринно и вечерно правило', text: 'Молитвеното правило е постоянен ред от молитви, които християнинът казва всеки ден, обикновено сутрин и вечер. То е като тренировъчен план – стойността му идва от редовността, а не от еднократния подвиг. В молитвеника има готови утринни и вечерни молитви, но правилото може да е и по-кратко, съобразено с живота ти, най-добре след съвет с духовника. Сутрин посвещаваме деня на Бога, а вечер благодарим и преглеждаме съвестта си. По-добре кратко правило, изпълнявано с внимание всеки ден, отколкото дълго, което скоро изоставяш.', read: 'Пс. 5:3–4; „Православен молитвеник“ – утринни и вечерни молитви' },
  { id: 'b010', cat: 'Светите отци и светии', title: 'Св. Ириней Лионски', text: 'Свети Ириней (II в.) е родом от Мала Азия и като младеж слушал св. Поликарп Смирненски, ученик на апостол Йоан. По-късно станал епископ на Лион в Галия. В съчинението си „Против ересите“ разобличил гностиците, които презирали материята и тялото. Той учел, че Христос „възглавява“ в Себе Си цялото човечество и обновява творението. Известна е мисълта му, че славата Божия е живият човек, а животът на човека е да вижда Бога.', read: 'Еф. 1:10; св. Ириней Лионски, „Против ересите“, кн. 4' },
  { id: 'b011', cat: 'Църковна история', title: 'Апостолският събор', text: 'Около средата на I век в Църквата възникнал спор дали езичниците, приели Христос, трябва да се обрязват и да спазват целия Моисеев закон. Апостолите и презвитерите се събрали в Йерусалим, за да решат въпроса заедно. След речите на Петър и Яков те постановили, че езичниците не бива да се обременяват, освен с няколко необходими неща. Решението било изразено с думите: „Угодно бе на Светия Дух и на нас“. Този събор е образец за съборното решаване на въпросите в Православната църква.', read: 'Деян. 15:1–29; Гал. 2:1–10' },
  { id: 'b012', cat: 'Християнски живот', title: 'Дълговете', text: 'Писанието предупреждава, че „длъжникът става роб на заемодавеца“. Дългът, взет за лукс, за да впечатлим другите, често носи тревога, кавги в дома и изкушение към нечестност. Християнинът живее според възможностите си и предпочита скромност пред показност. Ако вече си задлъжнял, трябва честно да погледнеш истината, да направиш план и да връщаш постепенно, без да бягаш от отговорност. Апостол Павел казва: „Не дължете никому нищо освен взаимна любов“.', read: 'Притч. 22:7; Римл. 13:8' },
  { id: 'b013', cat: 'Духовен живот', title: 'Исихазмът', text: 'Исихазмът (от гръцкото „исихия“ – тишина, безмълвие) е древната православна традиция на вътрешна молитва. Целта ѝ е умът да слезе в сърцето и човекът да се съедини с Бога чрез непрестанната Иисусова молитва. Тя изисква пазене на помислите, трезвение, смирение и живот в Църквата с тайнствата. Исихастите учат, че очистеният човек може да вкуси нетварната Божия светлина, която апостолите видели на Тавор. За мирянина това означава поне малко ежедневна тишина и молитва, в която да спре шума около себе си.', read: 'Мат. 6:6; „Добротолюбие“, св. Григорий Синаит' },
  { id: 'b014', cat: 'Светите отци и светии', title: 'Св. Атанасий Велики', text: 'Свети Атанасий (IV в.) е бил архиепископ на Александрия и главен защитник на никейската вяра срещу арианството. Заради вярата си бил изпращан в изгнание пет пъти, но не отстъпил. В книгата „За въплъщението на Словото“ обяснява, че само Бог може да спаси човека от смъртта, затова Словото Божие стана човек. Отците обобщават тази мисъл така: Бог стана човек, за да може човекът да стане бог по благодат. Той показва, че истината понякога се пази от малцина, които са готови да платят цена.', read: 'Йоан 1:1–14; св. Атанасий Велики, „За въплъщението на Словото“' },
  { id: 'b015', cat: 'Църковна история', title: 'Гонението при Нерон', text: 'През 64 г. голям пожар опустошил Рим и император Нерон обвинил християните. Мнозина били измъчвани и убити с особена жестокост. Според църковното предание в този период в Рим пострадали апостолите Петър и Павел – Петър разпнат с главата надолу, а Павел посечен с меч. Така започнали гоненията, които с прекъсвания продължили почти три века. Кръвта на мъчениците, както казва Тертулиан, станала семе на християнството.', read: 'Йоан 21:18–19; 2 Тим. 4:6–8' },
  { id: 'b016', cat: 'Християнски живот', title: 'Алчността', text: 'Алчността е ненаситното желание да имаш все повече, дори когато имаш достатъчно. Христос разказва притчата за богаташа, който строял по-големи хамбари, но същата нощ душата му била поискана. Алчността прави човека твърд към бедните, тревожен и недоверчив към Бога. Лекарството е благодарността за това, което имаш, и щедростта, която разхлабва хватката на парите върху сърцето. Опитай се съзнателно да дадеш нещо, за което ти е мъчно – това е добро упражнение срещу алчността.', read: 'Лука 12:13–21; Евр. 13:5' },
  { id: 'b017', cat: 'Духовен живот', title: 'Покаянието', text: 'Гръцката дума за покаяние, „метаноя“, означава промяна на ума, обръщане на целия живот към Бога. То не е само съжаление или чувство на вина, а решение да се върнеш у дома като блудния син. Покаянието започва с честно виждане на греха, продължава с изповед и завършва с ново поведение. Отците казват, че то не е еднократно, а трае до последния ни дъх. Покаянието е изпълнено с надежда, защото Бог тича към завръщащия се, преди той да е стигнал до дома.', read: 'Лука 15:11–32; св. Йоан Лествичник, „Лествица“, Слово 5' },
  { id: 'b018', cat: 'Светите отци и светии', title: 'Св. Василий Велики', text: 'Свети Василий (IV в.) е бил архиепископ на Кесария Кападокийска, богослов, пастир и организатор на монашеския живот. Той защитавал божеството на Светия Дух и написал трактата „За Светия Дух“. Край Кесария изградил цял комплекс за бедни, болни и странници, наричан Василиада. Неговите монашески правила съчетават молитва, труд и служение на ближния. Литургията на св. Василий и днес се служи няколко пъти в годината, включително по Великия пост.', read: 'Мат. 25:31–46; св. Василий Велики, беседа „Ще съборя житниците си“' },
  { id: 'b019', cat: 'Църковна история', title: 'Гонението при Диоклециан', text: 'Най-жестокото гонение срещу християните започнало през 303 г. при император Диоклециан. Издадени били укази за разрушаване на храмове, изгаряне на свещените книги и принуждаване на християните да принасят жертви на боговете. Хиляди мъже, жени и деца загинали, сред тях много войници като св. Георги и св. Димитър. Някои паднали от страх, а после въпросът как да бъдат приети обратно занимавал Църквата. Това гонение показва, че вярата е въпрос на живот, а не само на убеждение.', read: 'Откр. 2:10; Евсевий Кесарийски, „Църковна история“, кн. 8' },
  { id: 'b020', cat: 'Християнски живот', title: 'Хазартът и залаганията', text: 'Хазартът обещава лесна печалба без труд, но всъщност се храни от алчността и надеждата в късмета вместо в Бога. Той лесно поражда зависимост, която разрушава семейства, приятелства и самоуважение. В света на спорта залаганията са и изкушение към нечестност и уреждане на резултати. Християнинът печели хляба си с труд и не поставя бъдещето на семейството си на карта. Ако усещаш, че залаганията те владеят, кажи го на изповед и потърси помощ – това не е слабост, а мъжество.', read: 'Притч. 13:11; 1 Тим. 6:9–10' },
  { id: 'b021', cat: 'Духовен живот', title: 'Тайнството Изповед', text: 'Изповедта е тайнство, в което християнинът изповядва греховете си пред Бога в присъствието на свещеника и получава опрощение. Свещеникът е свидетел и служител, а прощава Сам Христос, Който даде на апостолите властта да опрощават грехове. Подготовката включва преглед на съвестта, искрено съжаление и решимост за промяна. Говори конкретно и просто, без самооправдание и без да обвиняваш другите. След изповед човек често усеща лекота – като след тежка тренировка, когато е изхвърлил всичко ненужно.', read: 'Йоан 20:22–23; 1 Йоан 1:8–9' },
  { id: 'b022', cat: 'Светите отци и светии', title: 'Св. Григорий Богослов', text: 'Свети Григорий Назиански (IV в.) е приятел на св. Василий Велики и един от тримата светители, наречени Богослови. Бил човек на тишината и поезията, но Бог го повикал в Константинопол, където в малка църква защитавал никейската вяра. Неговите „Пет богословски слова“ са сред най-дълбоките текстове за Света Троица. За кратко председателствал Втория вселенски събор, но се оттеглил, за да запази мира. Той учи, че за Бога се говори с чисто сърце, а не само с остър ум.', read: 'Мат. 28:19; св. Григорий Богослов, „Пет богословски слова“' },
  { id: 'b023', cat: 'Църковна история', title: 'Миланският едикт', text: 'През 313 г. императорите Константин и Лициний обявили религиозна търпимост в Римската империя, известна като Миланския едикт. Християните получили свобода да изповядват вярата си и им били върнати конфискуваните имоти. Константин, който по-късно приел кръщение, подкрепял Църквата и свикал Първия вселенски събор. Църквата го почита заедно с майка му св. Елена като равноапостолни. Свободата донесла и нови изкушения – светскост и съблазън от властта, срещу които мнозина отговорили с бягство в пустинята.', read: 'Евсевий Кесарийски, „Живот на Константин“; Римл. 13:1–7' },
  { id: 'b024', cat: 'Християнски живот', title: 'Спекулации и лесни пари', text: 'Съвременният свят е пълен с обещания за бързо забогатяване – схеми, рискови залози и „сигурни“ инвестиции. Зад тях често стоят нетърпение, алчност и желание да избегнем честния труд. Писанието казва, че имотът, придобит набързо, намалява, а събираният постепенно расте. Християнинът е разумен стопанин: не рискува това, което не може да загуби, и не взема решения от страх да не изпусне нещо. Преди голямо финансово решение се помоли, изчакай и се посъветвай с човек, когото уважаваш.', read: 'Притч. 13:11; Притч. 28:20' },
  { id: 'b025', cat: 'Духовен живот', title: 'Плачът и сълзите', text: 'Отците говорят за „радостотворен плач“ – скръб за греховете, която не смазва, а очиства и носи утеха. Христос казва: „Блажени плачещите, защото те ще бъдат утешени“. Тук не става дума за самосъжаление или депресия, а за сърце, което е престанало да бъде каменно. Сълзите на покаянието отците сравняват с второ кръщение. Ако нямаш сълзи, не се насилвай – моли Бога за сокрушено сърце и Той ще го даде в Своето време.', read: 'Мат. 5:4; св. Йоан Лествичник, „Лествица“, Слово 7' },
  { id: 'b026', cat: 'Светите отци и светии', title: 'Св. Григорий Нисийски', text: 'Свети Григорий, епископ на Ниса (IV в.), е по-малкият брат на св. Василий Велики и един от най-дълбоките мислители на Църквата. Заедно с Василий и Григорий Богослов той е сред тримата Кападокийци, които изясняват учението за Света Троица. В „Животът на Мойсей“ описва духовния път като безкрайно възхождане към Бога. Според него съвършенството не е спиране, а непрестанен растеж от слава в слава. Тази мисъл е утешителна: в духовния живот никога не е късно и никога не е „достатъчно“.', read: 'Фил. 3:13–14; св. Григорий Нисийски, „Животът на Мойсей“' },
  { id: 'b027', cat: 'Църковна история', title: 'Раждането на монашеството', text: 'През IV век, когато гоненията свършили, много християни потърсили нов вид мъченичество – отказ от света в пустинята. В Египет св. Антоний Велики дал пример за отшелнически живот, а св. Пахомий Велики организирал общежителни манастири с общ устав. Скоро монашеството се разпространило в Палестина, Сирия и Мала Азия. Изреченията на пустинните отци и до днес са съкровищница на практическа мъдрост. Монасите не бягат от хората от омраза, а за да се молят за целия свят.', read: '„Отечник“ (Изречения на пустинните отци); Мат. 19:21' },
  { id: 'b028', cat: 'Християнски живот', title: 'Гневът в залата и извън нея', text: 'В бойния спорт агресията лесно се бърка със сила, а гневът – с мотивация. Отците учат, че гневът е даден на човека, за да се бори срещу греха и злото, а не срещу ближния. Боецът, който се гневи, губи яснота и контрол – това знае всеки добър треньор. Христос предупреждава, че който се гневи напразно на брата си, подлежи на съд. Упражнявай спокойствието в залата: удряй с пълна сила, но без омраза, и остави противника в клетката.', read: 'Мат. 5:21–24; Иак. 1:19–20' },
  { id: 'b029', cat: 'Духовен живот', title: 'Чревоугодие и въздържание', text: 'Чревоугодието е първата от осемте главни страсти, описани от отците. То е не само преяждане, но и прекалено внимание към вкуса, лакомия и ядене извън време. Въздържанието е противоположната добродетел – да ядеш толкова и такова, каквото е нужно, и да пазиш постите. Отците казват, че който владее стомаха си, по-лесно владее и другите страсти. За спортиста това е близко: режимът на хранене е дисциплина, която може да се превърне и в духовна, ако се прави за Бога.', read: '1 Кор. 9:25–27; св. Йоан Касиан Римлянин, „За осемте главни помисли“' },
  { id: 'b030', cat: 'Светите отци и светии', title: 'Св. Йоан Златоуст', text: 'Свети Йоан (IV–V в.) бил проповедник в Антиохия, а после архиепископ на Константинопол. Заради красноречието си е наречен Златоуст. Той безстрашно изобличавал разкоша на богатите и несправедливостта към бедните, дори в императорския двор, и затова бил изпратен в изгнание, където починал. Последните му думи били: „Слава на Бога за всичко!“. Божествената литургия, която служим почти всяка неделя, носи неговото име.', read: 'Св. Йоан Златоуст, „Беседи върху Евангелието от Матей“; Мат. 25:40' },
  { id: 'b031', cat: 'Църковна история', title: 'Първи вселенски събор', text: 'През 325 г. император Константин свикал в Никея Първия вселенски събор. Причина било учението на Арий, че Синът Божий е творение и не е вечен. Отците изповядали, че Синът е „единосъщен“ с Отца – Бог истинен от Бога истинен. Тогава била съставена първата част на Символа на вярата и бил уреден въпросът за датата на Пасха. Сред участниците предание споменава св. Николай Мирликийски и св. Спиридон Тримитунтски.', read: 'Йоан 10:30; Символ на вярата, членове 1–7' },
  { id: 'b032', cat: 'Християнски живот', title: 'Самообладанието', text: 'Самообладанието е плод на Светия Дух, споменат от апостол Павел. То означава човек да владее езика, погледа, апетита и реакциите си, а не те него. Притчи казва, че дълготърпеливият е по-добър от храбреца, а владеещият себе си – от онзи, който превзема град. Боецът знае колко струва контролът под натиск; същото важи и в семейството, на пътя и в интернет. Упражнявай се в малки неща: изчакай преди да отговориш, откажи си нещо дребно, довърши започнатото.', read: 'Гал. 5:22–23; Притч. 16:32' },
  { id: 'b033', cat: 'Духовен живот', title: 'Блуд и целомъдрие', text: 'Страстта на блуда е изкривяване на дадената от Бога сила на любовта и привличането. Тя започва с помисъла и погледа, преди да стигне до делото, затова Христос говори за прелюбодейство в сърцето. Целомъдрието не е просто въздържание, а цялостност на ума и тялото, които принадлежат на Бога. Отците съветват пазене на очите, пост, молитва, труд и честна изповед, без отчаяние при падане. Тази борба е трудна за всеки мъж, но Бог дава сила на онзи, който не се предава.', read: 'Мат. 5:27–30; 1 Кор. 6:18–20' },
  { id: 'b034', cat: 'Светите отци и светии', title: 'Св. Ефрем Сирин', text: 'Свети Ефрем (IV в.) е живял в Нисибис и Едеса и е наречен „Арфата на Светия Дух“ заради своите химни. Той пишел на сирийски език богословие под формата на поезия, за да учи народа на правата вяра. Бил е дякон и смирено отказвал по-високи служби. Покайната му молитва „Господи и Владико на живота ми“ се чете по време на Великия пост с поклони. Тя иска избавление от леност, униние, властолюбие и празнословие и дар на целомъдрие, смирение, търпение и любов.', read: 'Молитвата на св. Ефрем Сирин; Пс. 140:3' },
  { id: 'b035', cat: 'Църковна история', title: 'Втори вселенски събор', text: 'Вторият вселенски събор се събрал в Константинопол през 381 г. при император Теодосий Велики. Той осъдил учението на духоборците (пневматомахите), които отричали божеството на Светия Дух. Отците допълнили Символа на вярата с членовете за Светия Дух, Църквата, кръщението и възкресението. Така се оформил Никео-Цариградският символ, който изповядваме и днес. Голяма роля за подготовката изиграли Кападокийските отци.', read: 'Йоан 15:26; Символ на вярата, член 8' },
  { id: 'b036', cat: 'Християнски живот', title: 'Християнинът и бойните спортове', text: 'Църквата не забранява спорта, а апостол Павел дори използва образи от борбата и състезанието, за да говори за духовния живот. Бойните спортове могат да възпитават дисциплина, смелост, търпение и уважение. Опасностите са в гордостта, омразата, жаждата за слава и умишленото нараняване, надхвърлящо правилата. Християнинът боец пази сърцето си: бие се честно, уважава противника и не превръща спорта в идол. Добре е да говориш за тези въпроси със своя духовник, за да носиш спорта си с чиста съвест.', read: '1 Кор. 9:24–27; 2 Тим. 2:5' },
  { id: 'b037', cat: 'Духовен живот', title: 'Сребролюбие и нестяжание', text: 'Сребролюбието е страст, която кара човека да търси сигурност и стойност в притежанията. Тя е коварна, защото може да съжителства с иначе благоприличен живот. Противоположната добродетел е нестяжанието – свобода от привързаност към вещите, дори когато ги имаш. Отците съветват да даваш милостиня, да не трупаш излишно и да благодариш за насъщното. Свободният от сребролюбие човек спи спокойно, защото знае, че Бог е неговото наследство.', read: 'Мат. 6:19–24; св. Йоан Лествичник, „Лествица“, Слова 16–17' },
  { id: 'b038', cat: 'Светите отци и светии', title: 'Св. Макарий Египетски', text: 'Свети Макарий Велики (IV в.) е един от великите отци в египетската пустиня Скит. Още млад придобил такава мъдрост, че го наричали „младия старец“. Известен бил с кротостта си: когато бил несправедливо обвинен, не се оправдавал, а търпеливо понасял. Под неговото име са запазени „Духовни беседи“, които говорят за сърцето като място, където живее Бог. Неговият съвет за молитвата е прост: „Господи, както искаш и както знаеш, помилуй ме“.', read: 'Св. Макарий Египетски, „Духовни беседи“; Лука 17:21' },
  { id: 'b039', cat: 'Църковна история', title: 'Трети вселенски събор', text: 'През 431 г. в Ефес се събрал Третият вселенски събор. Константинополският архиепископ Несторий учел, че Дева Мария трябва да се нарича Христородица, а не Богородица, разделяйки Христос на две лица. Събор, воден от св. Кирил Александрийски, изповядал, че Христос е едно Лице – въплътеното Слово Божие. Затова Мария наистина е Богородица, защото роденият от нея е Бог. Почитта към Богородица е тясно свързана с правата вяра за Христос.', read: 'Лука 1:43; Йоан 1:14' },
  { id: 'b040', cat: 'Християнски живот', title: 'Насилието – кога е грях', text: 'Православната традиция цени мира и никога не прославя насилието само по себе си. Защитата на слабия, на семейството и на родината е допустима, но отнемането на живот, дори във война, се смята за рана на душата. Св. Василий Велики съветва войниците, които са убивали, да се въздържат известно време от Причастие. Християнинът не търси бой, не провокира и не отмъщава. Силата, която Бог ти е дал, е за защита и служение, а не за унижение на другите.', read: 'Римл. 12:17–21; св. Василий Велики, Правило 13' },
  { id: 'b041', cat: 'Духовен живот', title: 'Гняв и кротост', text: 'Гневът е страст, която помрачава ума повече от всички други, казват отците. Той се проявява не само в избухване, но и в раздразнение, сърдене и тайни мисли за отмъщение. Противоположната добродетел е кротостта – тиха сила, която не се поддава на провокация. Христос казва: „Научете се от Мене, понеже съм кротък и смирен по сърце“. В момент на гняв мълчи, кажи наум Иисусовата молитва и не взимай решения, докато не се успокоиш.', read: 'Мат. 11:29; св. Йоан Лествичник, „Лествица“, Слово 8' },
  { id: 'b042', cat: 'Светите отци и светии', title: 'Св. Николай Чудотворец', text: 'Свети Николай (III–IV в.) е бил архиепископ на град Мира в Ликия и е един от най-обичаните светии в православния свят. Преданието разказва как тайно помогнал на бедняк с три дъщери, хвърляйки злато в дома му. Защитил невинно осъдени, а по време на гонения бил хвърлен в затвор. Почитан е като покровител на моряци, пътници, деца и бедни. В България денят му, Никулден, се празнува на 6 декември.', read: 'Мат. 6:3–4; тропар на св. Николай „Правило на вярата“' },
  { id: 'b043', cat: 'Църковна история', title: 'Четвърти вселенски събор', text: 'Четвъртият вселенски събор се събрал в Халкидон през 451 г. Той осъдил монофизитството на Евтихий, според което човешката природа на Христос била погълната от божествената. Отците изповядали, че Христос е един и същ, съвършен Бог и съвършен човек, в две природи. Те се съединяват „неслитно, неизменно, неразделно и неразлъчно“ в едно Лице. Това означава, че Христос наистина е взел нашата човешка природа, за да я изцели отвътре.', read: 'Евр. 4:15; Фил. 2:5–11' },
  { id: 'b044', cat: 'Християнски живот', title: 'Мъжеството', text: 'Мъжеството е една от главните добродетели и означава твърдост пред опасност, болка и изкушение. Истинската смелост не е липса на страх, а избор да постъпиш правилно въпреки него. Мъчениците са най-смелите хора в историята: те не удряли, но и не се отрекли. Понякога е по-трудно да признаеш грешка, да поискаш прошка или да защитиш вярата си пред приятели, отколкото да влезеш в ринга. Помоли Бога за мъжеството, което Му е угодно, а не за това, което впечатлява хората.', read: 'Ис. Нав. 1:9; 1 Кор. 16:13' },
  { id: 'b045', cat: 'Духовен живот', title: 'Печал и духовна радост', text: 'Отците различават две печали: „печал по Бога“, която води към покаяние, и светска печал, която води към смърт. Страстната печал идва от неизпълнени желания, обиди и загуби и затваря човека в самия него. Лекарство срещу нея са молитвата, благодарността, разговорът с духовника и грижата за другите. Радостта на християнина не зависи от обстоятелствата, а от присъствието на Възкръсналия Христос. Тя може да съществува дори посред скръб, като тиха светлина в тъмна стая.', read: '2 Кор. 7:10; Фил. 4:4–7' },
  { id: 'b046', cat: 'Светите отци и светии', title: 'Четиридесетте мъченици', text: 'В началото на IV век в Севастия четиридесет войници християни отказали да принесат жертва на идолите. Хвърлили ги голи в замръзнало езеро, а на брега била приготвена топла баня за онзи, който се отрече. Един не издържал и избягал, но в същия миг стражът, видял светли венци над мъчениците, се обявил за християнин и заел мястото му. Мъчениците се насърчавали един друг до сутринта. Те са пример за братство, издръжливост и вярност до край.', read: 'Св. Василий Велики, „Беседа за светите четиридесет мъченици“; Откр. 2:10' },
  { id: 'b047', cat: 'Църковна история', title: 'Пети вселенски събор', text: 'Петият вселенски събор се състоял в Константинопол през 553 г. при император Юстиниан. Той осъдил т.нар. „Три глави“ – съчинения на трима богослови, близки до несторианството. Целта била да се потвърди Халкидонската вяра и да се търси помирение с онези, които я отхвърляли. Съборът осъдил и някои учения, свързани с Ориген, като предсъществуването на душите. Решенията му потвърждават, че в Христос е едно Лице – въплътеният Бог Слово.', read: 'Йоан 1:14; Кол. 2:9' },
  { id: 'b048', cat: 'Християнски живот', title: 'Тялото – храм на Духа', text: 'Православието не презира тялото – Бог го е създал, Христос го прие и то ще възкръсне. Апостол Павел казва, че тялото ни е храм на Светия Дух и че с него трябва да прославяме Бога. Затова грижата за тялото е добра, когато е подчинена на духа: здраве, сила и чистота. Опасно е, когато тялото стане идол – образ в огледалото, мускули за показ, или пък обект на злоупотреба с химия. Тренирай, за да служиш по-добре, а не за да бъдеш обожаван.', read: '1 Кор. 6:19–20; Римл. 12:1' },
  { id: 'b049', cat: 'Духовен живот', title: 'Униние и бодрост', text: 'Унинието (акедия) е страст на отпускане, скука и безсилие, при която всичко духовно изглежда безсмислено. Отците го наричат „пладнешкия бяс“, защото напада особено в средата на деня и на пътя. То шепне: „Утре ще започнеш“, „Няма смисъл“, „Не ти е за теб“. Лекарството е търпение, малки редовни задачи, ръчен труд и мисъл за смъртта и вечността. Не чакай да ти се прииска да се молиш – започни и желанието ще дойде, както идва силата по време на загрявката.', read: 'Пс. 90:6; св. Йоан Лествичник, „Лествица“, Слово 13' },
  { id: 'b050', cat: 'Светите отци и светии', title: 'Св. Максим Изповедник', text: 'Свети Максим (VII в.) е един от най-дълбоките богослови на Църквата. Той защитавал истината, че Христос има две воли – божествена и човешка, които действат в пълна хармония. Заради тази вяра на стари години му отрязали езика и дясната ръка и го изпратили в изгнание, където починал. Учението му е потвърдено на Шестия вселенски събор. В „Глави за любовта“ той учи, че всички заповеди водят към любовта, а тя – към Бога.', read: 'Мат. 26:39; св. Максим Изповедник, „Четиристотин глави за любовта“' },
  { id: 'b051', cat: 'Църковна история', title: 'Шести вселенски събор', text: 'Шестият вселенски събор заседавал в Константинопол през 680–681 г. Той осъдил монотелитството – учението, че в Христос има само една воля. Отците изповядали, че Христос има две природни воли и две действия, като човешката воля свободно се подчинява на божествената. Това е важно за нашето спасение: Христос е изцелил и човешката воля, като в Гетсимания е казал „Не Моята воля, а Твоята да бъде“. Така Той ни показва пътя на свободното послушание към Бога.', read: 'Лука 22:42; св. Максим Изповедник, „Диспут с Пир“' },
  { id: 'b052', cat: 'Християнски живот', title: 'Здравето и грижата за тялото', text: 'Здравето е Божи дар, който сме длъжни да пазим, без да го превръщаме в най-висша ценност. Сънят, храненето, възстановяването и лечението са част от добрата грижа, а пренебрегването им може да е проява на гордост. Отците никога не забраняват лекарите – Сирах казва да почиташ лекаря, защото и него Господ го е създал. В същото време християнинът се моли за изцеление и приема Тайнството Елеосвещение. Тялото е съд на душата: грижи се за него така, че да може да служи дълго.', read: 'Сир. 38:1–15; Иак. 5:14–15' },
  { id: 'b053', cat: 'Духовен живот', title: 'Тщеславието', text: 'Тщеславието е жажда за човешка похвала и одобрение. То е хитро, защото може да се храни дори от добрите ни дела – от поста, молитвата, милостинята. Христос съветва да даваме тайно, да се молим в стаята си и да постим, без да показваме това. Добродетелта, противоположна на тщеславието, е скромността – да вършиш доброто заради Бога, а не заради публиката. В ерата на социалните мрежи е полезно да се питаме: бих ли го направил, ако никой не разбере?', read: 'Мат. 6:1–18; св. Йоан Лествичник, „Лествица“, Слово 22' },
  { id: 'b054', cat: 'Светите отци и светии', title: 'Св. Георги Победоносец', text: 'Свети Георги е бил войник в римската армия по времето на Диоклециан. Когато започнало гонението, той открито изповядал вярата си пред императора и бил подложен на тежки мъчения, след което бил обезглавен. Иконата с него на кон, пробождащ змея, е образ на победата над злото чрез вярата. В България Гергьовден, 6 май, е и ден на храбростта и на Българската армия. Той е покровител на войниците и на всички, които се борят честно.', read: 'Еф. 6:10–17; житие на св. Георги (Четьи-минеи, 23 април ст.ст.)' },
  { id: 'b055', cat: 'Църковна история', title: 'Седми вселенски събор', text: 'Седмият вселенски събор се събрал в Никея през 787 г., по времето на императрица Ирина. Той осъдил иконоборството и възстановил почитането на светите икони. Отците направили важно разграничение: на иконите се отдава почит и поклонение, а служение (латрия) се дължи само на Бога. Почитта към образа преминава към изобразения. Тъй като Бог стана видим човек в Христос, Той може да бъде изобразяван.', read: 'Йоан 1:14; Кол. 1:15' },
  { id: 'b056', cat: 'Християнски живот', title: 'Дисциплината', text: 'Всеки спортист знае, че резултатите идват от дисциплината – ежедневни, често скучни повторения. Същото важи и за духовния живот: молитвеното правило, постът и редовната Литургия изграждат душата постепенно. Апостол Павел пише, че всеки състезател се въздържа от всичко, за да получи тленен венец, а ние – нетленен. Дисциплината не е самоцел, а средство за свобода: който владее навиците си, е свободен. Избери едно малко духовно правило и го пази всеки ден, както пазиш тренировъчния си график.', read: '1 Кор. 9:24–27; Евр. 12:11' },
  { id: 'b057', cat: 'Духовен живот', title: 'Гордост и смирение', text: 'Гордостта е последната и най-тежка от осемте страсти – грехът, с който паднал Луцифер. Тя кара човека да си приписва заслугите, да презира другите и да не иска помощ дори от Бога. Отците казват, че гордостта може да унищожи всички добродетели, а смирението да покрие много грехове. Смирението не е унижение или ниско самочувствие, а истинско знание за себе си: всичко добро е дар от Бога. „Бог се противи на горделивите, а на смирените дава благодат“.', read: 'Иак. 4:6; св. Йоан Лествичник, „Лествица“, Слова 23 и 25' },
  { id: 'b058', cat: 'Светите отци и светии', title: 'Св. Димитър Солунски', text: 'Свети Димитър е бил знатен човек и според преданието управител в Солун по времето на император Максимиан. Той проповядвал Христос открито и затова бил хвърлен в тъмница. Преданието разказва как благословил младия Нестор да излезе срещу силния гладиатор Лий, когото Нестор победил – след което и двамата били убити. Солун почита св. Димитър като свой небесен защитник. Той е образ на християнина, който съчетава смелост, вяра и грижа за по-младите.', read: 'Житие на св. Димитър Солунски (26 октомври); 1 Йоан 5:4' },
  { id: 'b059', cat: 'Църковна история', title: 'Тържеството на Православието', text: 'След Седмия вселенски събор иконоборството се възобновило през IX век. Окончателно почитането на иконите било възстановено през 843 г. при императрица Теодора. Това събитие се празнува всяка година в първата неделя на Великия пост като Неделя на Православието. На тази служба се прочита Синодикът, който прославя защитниците на вярата. Празникът ни напомня, че вярата се пази с цената на страдания и че иконата е изповед на въплъщението.', read: '„Синодик в Неделята на Православието“; св. Йоан Дамаскин, „Три слова в защита на иконите“' },
  { id: 'b060', cat: 'Християнски живот', title: 'Целомъдрие преди брака', text: 'Църквата учи, че интимната близост има своето място в брака, където тя е израз на пълно и вярно себеотдаване. Това е трудно в култура, която представя случайните връзки като нещо нормално. Целомъдрието не е потискане, а пазене на силата на любовта за човека, с когото ще изградиш семейство. Помагат ясни граници, пазене на погледа, приятелства с хора с вяра, пост и редовна изповед. Ако си падал, не се отчайвай – покаянието възстановява и благодатта лекува.', read: '1 Кор. 6:18–20; 1 Сол. 4:3–5' },
  { id: 'b061', cat: 'Духовен живот', title: 'Трезвението', text: 'Трезвението е будно внимание към собственото сърце и помисли. Отците го сравняват с пазач на вратата, който проверява всеки, който иска да влезе. То започва с малко: да забележиш помисъла на гняв или похот още в зародиш и да го отхвърлиш с молитва. Св. Исихий Презвитер казва, че трезвението и Иисусовата молитва вървят заедно като дишането. За боеца е лесно разбираемо – както в ринга не изпускаш противника от поглед, така и в душата си пазиш стража.', read: '1 Петр. 5:8; св. Исихий Презвитер, „За трезвението и добродетелта“ (Добротолюбие)' },
  { id: 'b062', cat: 'Светите отци и светии', title: 'Св. Теодор Стратилат', text: 'Свети Теодор Стратилат бил военачалник (стратилат) в град Ираклия в началото на IV век. Той бил известен със смелостта и мъдростта си и проповядвал Христос сред жителите на града. Когато император Лициний поискал да принесе жертва на идолите, Теодор взел златните им статуи, разбил ги и раздал парчетата на бедните. Претърпял жестоки мъчения и бил обезглавен. Той показва, че служебната власт и сила трябва да се подчиняват на Бога.', read: 'Житие на св. Теодор Стратилат (8 февруари); Деян. 5:29' },
  { id: 'b063', cat: 'Църковна история', title: 'Символът на вярата', text: 'Символът на вярата, който четем на всяка Литургия, е кратко обобщение на православното учение, утвърдено на Първия и Втория вселенски събор. Той изповядва вярата в Единия Бог Отец, в Иисус Христос – единосъщния Син, и в Светия Дух, Който изхожда от Отца. Изповядва и Църквата, кръщението, възкресението на мъртвите и живота на бъдещия век. Православната църква пази Символа без добавката „и от Сина“ (Филиокве), приета по-късно на Запад. Полезно е да го знаеш наизуст и да го казваш съзнателно всеки ден.', read: 'Символ на вярата; Йоан 15:26' },
  { id: 'b064', cat: 'Християнски живот', title: 'Чистотата на погледа', text: 'Порнографията е една от най-разпространените зависимости днес и засяга вярващи и невярващи. Тя превръща човека в обект, изкривява представата за любовта и ослабва способността за истинска близост. Христос казва, че ако окото те съблазнява, трябва решително да отсечеш източника на съблазън. На практика това означава филтри, телефонът да не е в спалнята нощем, отчетност пред приятел и изповед. Борбата може да е дълга, но всеки ден на свобода е победа – не се отчайвай при падане.', read: 'Мат. 5:28–29; Пс. 100:3' },
  { id: 'b065', cat: 'Духовен живот', title: 'Как действат помислите', text: 'Отците описват как грехът се ражда постепенно. Първо идва прилогът – мисъл или образ, който сам по себе си не е грях. След това следват събеседването с помисъла, съгласието, пленяването и накрая страстта, вкоренена чрез навика. Най-лесно е да отхвърлиш помисъла в самото начало, преди да си започнал да разговаряш с него. Затова се казва: не спори с лошата мисъл, а се обърни към Христос в молитва.', read: 'Иак. 1:14–15; св. Йоан Лествичник, „Лествица“, Слово 15' },
  { id: 'b066', cat: 'Светите отци и светии', title: 'Св. Теодор Тирон', text: 'Свети Теодор Тирон бил млад новобранец (тирон) в римската армия в началото на IV век. Отказал да принесе жертва на боговете и подпалил езически храм, за което бил изгорен. Половин век по-късно император Юлиан Отстъпник наредил храната на пазарите в Константинопол да бъде поръсена с идоложертвена кръв през първата седмица на поста. Св. Теодор се явил на епископа и го посъветвал християните да ядат варено жито. В памет на това първата събота на Великия пост е Тодорова събота.', read: 'Житие на св. Теодор Тирон; служба на Тодорова събота' },
  { id: 'b067', cat: 'Църковна история', title: 'Мисията на Кирил и Методий', text: 'През 862 г. моравският княз Ростислав поискал от Византия учители, които да проповядват на славянски език. Император Михаил III изпратил братята Константин-Кирил и Методий от Солун. Още преди това Кирил създал глаголицата и братята превели богослужебните книги. В Моравия те срещнали силна съпротива от немското духовенство, което признавало само латински, гръцки и еврейски. В Рим папата одобрил славянската служба, но след смъртта на Методий през 885 г. учениците му били изгонени.', read: 'Пространно житие на св. Константин-Кирил Философ; Деян. 2:8–11' },
  { id: 'b068', cat: 'Християнски живот', title: 'Бракът като тайнство', text: 'В Православната църква бракът е тайнство, в което Бог съединява мъжа и жената в едно и им дава благодат за общия път. По време на венчанието над главите на младоженците се поставят венци – знак на царска слава, но и на мъченичество. Бракът е школа на любовта, в която двамата се учат на търпение, прошка и взаимна жертва. Апостол Павел сравнява любовта на мъжа към жена му с любовта на Христос към Църквата, Който даде Себе Си за нея. Добрият брак се гради с молитва заедно, честен разговор и уважение.', read: 'Еф. 5:21–33; Бит. 2:24' },
  { id: 'b069', cat: 'Духовен живот', title: 'Невидимата бран', text: 'Християнският живот е борба – не срещу хора, а срещу страстите и злите духове. Апостол Павел описва „всеоръжието Божие“: пояс на истината, броня на правдата, щит на вярата, шлем на спасението и меч на Духа – Божието слово. Св. Никодим Светогорец събрал наставленията за тази борба в книгата „Невидима бран“. Основните оръжия са недоверие в собствените сили, доверие в Бога, упражнение и молитва. Боецът знае, че губиш, ако подцениш противника – същото важи и в духовната битка.', read: 'Еф. 6:10–18; св. Никодим Светогорец, „Невидима бран“' },
  { id: 'b070', cat: 'Светите отци и светии', title: 'Св. Мина', text: 'Свети Мина бил египтянин и войник в римската армия в края на III век. Когато започнали гоненията, той напуснал службата и се оттеглил в планината в пост и молитва. По време на езически празник се явил открито и изповядал Христос пред тълпата и управителя. След мъчения бил обезглавен. Почитан е като покровител на семействата и на онези, които търсят изгубено, а празникът му е на 11 ноември.', read: 'Житие на св. Мина; Мат. 10:32–33' },
  { id: 'b071', cat: 'Църковна история', title: 'Покръстването на България', text: 'Княз Борис I приел християнството от Константинопол около 864–865 г., като получил името Михаил. Покръстването срещнало съпротива от част от болярите, но Борис го наложил твърдо. Той водил преговори и с Рим, докато през 870 г. на събор в Константинопол България получила своя архиепископия под Константинопол. През 886 г. Борис приел учениците на Кирил и Методий и им дал условия за работа. Така християнството станало основа на българската държава и култура.', read: '„Отговори на папа Николай I по допитванията на българите“; Деян. 16:9–10' },
  { id: 'b072', cat: 'Християнски живот', title: 'Семейството – домашна църква', text: 'Св. Йоан Златоуст нарича семейството „малка църква“. В него се учи вяра не толкова с думи, колкото с примера на родителите. Обща молитва преди хранене, кандило пред иконата, празнуване на имени дни и общо ходене на Литургия изграждат домашната църква. Семейството е и място за прошка – не лягайте си сърдити. Мъжът е призван да бъде първият, който служи, а не първият, който командва.', read: 'Еф. 5:21–6:4; св. Йоан Златоуст, Беседа 20 върху Послание към ефесяни' },
  { id: 'b073', cat: 'Духовен живот', title: 'Послушанието', text: 'Послушанието е отказ от собствената воля заради Божията воля, изразена чрез заповедите, Църквата и духовния наставник. То не е робство, а освобождаване от тиранията на собственото „аз“. Христос Сам бил послушен на Отца до смърт, и то кръстна. За мирянина послушанието се упражнява и в семейството, на работата и пред треньора – с доверие и без мърморене. Отците казват, че послушанието бързо води към смирение, а смирението – към мир.', read: 'Фил. 2:5–8; св. Йоан Лествичник, „Лествица“, Слово 4' },
  { id: 'b074', cat: 'Светите отци и светии', title: 'Св. Йоан Дамаскин', text: 'Свети Йоан Дамаскин (VII–VIII в.) е роден в Дамаск в християнско семейство, служило на арабския халиф. По-късно се оттеглил в Лавра на св. Сава край Йерусалим. Когато започнало иконоборството, той написал три слова в защита на иконите, в които обяснява, че въплъщението прави възможно изобразяването на Бога. Неговото „Точно изложение на православната вяра“ е класическо обобщение на догматите. Съставил е и много от песнопенията на Октоиха и Великденския канон.', read: 'Св. Йоан Дамаскин, „Точно изложение на православната вяра“; Великденски канон' },
  { id: 'b075', cat: 'Църковна история', title: 'Преславският събор от 893 г.', text: 'През 893 г. в Преслав се събрал народен събор, на който княз Борис-Михаил, вече монах, предал престола на сина си Симеон. Според историческите извори е решено столицата да се премести от Плиска в Преслав. Славянският език постепенно заменил гръцкия в богослужението и управлението. Това дало възможност народът да чува и разбира словото Божие на собствения си език. Решенията полагат основите на българската книжовност и култура.', read: 'Черноризец Храбър, „За буквите“; 1 Кор. 14:19' },
  { id: 'b076', cat: 'Християнски живот', title: 'Почит към родителите', text: 'Петата заповед казва: „Почитай баща си и майка си“, и е първата заповед с обещание. Почитта не означава безусловно съгласие, а уважение, благодарност и грижа, особено когато родителите остареят. Дори ако имаш наранявания от детството, Бог те призовава към прошка и към молитва за тях. Едно обаждане, посещение или помощ в домакинството често струват повече от много думи. Моли се за родителите си всеки ден – живи или починали.', read: 'Изх. 20:12; Еф. 6:1–3' },
  { id: 'b077', cat: 'Духовен живот', title: 'Духовният отец', text: 'В Православието никой не се спасява сам – нужен е опитен водач, духовник. Той помага да различиш помислите, да видиш страстите си и да избереш мярката на поста и молитвата. Отношенията с духовния отец се градят на доверие и откровеност, а не на сляпа зависимост. Добре е да се изповядваш редовно при един и същ свещеник, който познава живота ти. Ако още нямаш духовник, моли Бога да ти го прати и потърси свещеник, при когото усещаш мир и трезвост.', read: 'Евр. 13:17; св. Игнатий Брянчанинов, „Приношение към съвременното монашество“' },
  { id: 'b078', cat: 'Светите отци и светии', title: 'Св. Исаак Сирин', text: 'Свети Исаак (VII в.) за кратко бил епископ на Ниневия, но се оттеглил в пустинята, където прекарал живота си в молитва. Неговите „Подвижнически слова“ са сред най-четените книги в Православието. Той говори за „милостивото сърце“, което гори от любов към цялото творение – към хората, животните и дори към враговете. Учи, че смирението е дрехата на Божеството. Съветва да се помириш със себе си, и тогава небето и земята ще се помирят с теб.', read: 'Св. Исаак Сирин, „Подвижнически слова“; Лука 6:36' },
  { id: 'b079', cat: 'Църковна история', title: 'Преславската книжовна школа', text: 'Около столицата Преслав се развил голям книжовен център при княз Симеон. Там работили книжовници като Константин Преславски, Йоан Екзарх и Черноризец Храбър. Те превеждали богослужебни книги, проповеди и съчинения на отците и създавали оригинални творби. Тук вероятно се е утвърдила и кирилицата, по-лесна за писане от глаголицата. Тази епоха често се нарича Златен век на българската книжнина.', read: 'Черноризец Храбър, „За буквите“; Йоан Екзарх, „Шестоднев“' },
  { id: 'b080', cat: 'Християнски живот', title: 'Възпитанието на децата', text: 'Децата се учат на вяра най-вече като наблюдават родителите си. Апостол Павел съветва бащите да не дразнят децата си, а да ги възпитават в наставлението на Господа. Водете ги на Литургия и Причастие от малки, четете им библейски истории и житията на светиите. Строгостта трябва да е съчетана с много любов, време и внимание. За бащата спортист е полезно да показва на детето, че силата и смирението вървят заедно.', read: 'Еф. 6:4; Притч. 22:6' },
  { id: 'b081', cat: 'Духовен живот', title: 'Смисълът на поста', text: 'Постът не е диета, а духовна практика, която включва въздържание от храна, но и от гняв, клюки и развлечения. Чрез него човекът учи тялото да се подчинява на духа и освобождава време и сили за молитва и милосърдие. Отците казват, че постът без молитва и любов е „пост на демоните“, които никога не ядат. Мярката на поста трябва да се съобразява със здравето, работата и съвета на духовника. За спортист с тежки тренировки е особено важно да търси благословение за разумна мярка.', read: 'Ис. 58:3–7; Мат. 6:16–18' },
  { id: 'b082', cat: 'Светите отци и светии', title: 'Св. Йоан Лествичник', text: 'Свети Йоан (VII в.) прекарал около четиридесет години като отшелник в подножието на Синай, след което станал игумен на Синайския манастир. По молба на друг игумен той написал „Лествица“ – книга за духовното изкачване в тридесет стъпала. В нея с много точни наблюдения описва страстите и добродетелите. Книгата и до днес се чете в манастирите през Великия пост. Църквата го чества в четвъртата неделя на поста.', read: 'Бит. 28:12; св. Йоан Лествичник, „Лествица“' },
  { id: 'b083', cat: 'Църковна история', title: 'Охридската книжовна школа', text: 'През 886 г. св. Климент бил изпратен от княз Борис в областта Кутмичевица в днешна Македония. В Охрид и околностите той създал школа, в която обучил хиляди ученици да четат и пишат на славянски. По-късно се присъединил и св. Наум. Охридската школа запазила по-дълго глаголицата и оставила много проповеди и богослужебни текстове. Тя превърнала Охрид в един от най-важните духовни центрове на средновековна България.', read: 'Пространно житие на св. Климент Охридски; св. Климент Охридски, „Похвални слова“' },
  { id: 'b084', cat: 'Християнски живот', title: 'Прошката', text: 'Прошката е сърцето на християнския живот: в Господнята молитва казваме „и прости нам дълговете ни, както и ние прощаваме“. Да простиш не значи да кажеш, че злото не е било зло, нито непременно да се довериш отново. Значи да се откажеш от отмъщението и да предадеш съда на Бога. Понякога прошката е решение, преди да е чувство – започни с молитва за човека, който те е наранил. Неопростената обида е като отрова, която пиеш сам, надявайки се да навреди на другия.', read: 'Мат. 18:21–35; Мат. 6:12–15' },
  { id: 'b085', cat: 'Духовен живот', title: 'Постите в църковната година', text: 'Православната църква има четири дълги поста: Великият пост преди Пасха, Петровият пост, Богородичният пост през август и Коледният пост. Освен тях се пости всяка сряда и петък – в сряда заради предателството на Юда, в петък заради Разпятието. Има и еднодневни постове, като Кръстовден и Отсичането главата на св. Йоан Кръстител. Има и седмици без пост, например Светлата седмица след Великден. Постите подреждат времето така, че целият живот да върви в ритъма на Църквата.', read: 'Православен църковен календар; Марк 2:19–20' },
  { id: 'b086', cat: 'Светите отци и светии', title: 'Св. Кирил и Методий', text: 'Светите братя Кирил и Методий са родени в Солун през IX век. Методий бил управител на славянска област, а Константин-Кирил – учен, наречен Философ. Те създали славянската азбука и превели Свещеното Писание и богослужебните книги, за да може славянските народи да славят Бога на своя език. Кирил починал в Рим през 869 г., приемайки монашество, а Методий станал архиепископ и продължил делото до смъртта си през 885 г. Почитани са като равноапостолни, а 11 май е техният празник в Българската църква.', read: 'Пространни жития на Константин-Кирил и Методий; Пс. 150' },
  { id: 'b087', cat: 'Църковна история', title: 'Българската патриаршия при цар Симеон', text: 'Цар Симеон (893–927) превърнал България в една от най-силните държави в Европа. Той се стремял към пълна църковна независимост. След неговата смърт, с мира от 927 г. при цар Петър, Византия признала българския владетел за цар, а главата на Българската църква – за патриарх. Първият патриарх се смята Дамян със седалище в Дръстър (Силистра). Така Българската църква станала една от първите автокефални славянски църкви.', read: 'История на Българската православна църква – периодът на Първото българско царство' },
  { id: 'b088', cat: 'Християнски живот', title: 'Любовта към враговете', text: 'Най-радикалната заповед на Христос е: „Обичайте враговете си, благославяйте ония, които ви проклинат“. Тя не изисква да харесваш злото или да го оставяш без защита, а да желаеш доброто и спасението дори на този, който ти вреди. Христос се молел на Кръста за разпъващите Го: „Отче, прости им“. Св. Силуан Атонски учи, че любовта към враговете е мерило за истинската благодат. Започни с малко: кажи една кратка молитва за човек, който те е обидил.', read: 'Мат. 5:43–48; Лука 23:34' },
  { id: 'b089', cat: 'Духовен живот', title: 'Милостинята', text: 'Милостинята е дело на любовта, което Христос поставя редом с молитвата и поста. Тя включва не само пари, но и време, внимание, помощ, посещение на болен или затворник. Христос казва, че каквото направим за най-малкия от братята Му, на Него го правим. Отците учат, че ръката на бедния е „съкровищницата на Христос“. Давай тайно, с радост и без да съдиш дали човекът „заслужава“ – Бог ще съди за останалото.', read: 'Мат. 25:31–46; Мат. 6:2–4' },
  { id: 'b090', cat: 'Светите отци и светии', title: 'Св. Климент Охридски', text: 'Свети Климент е най-видният ученик на Кирил и Методий. След изгонването от Моравия пристигнал в България и бил изпратен от княз Борис в Охридската област. Там обучил хиляди ученици и написал множество проповеди и похвални слова на прост и разбираем език. По-късно бил ръкоположен за епископ. Починал през 916 г. и е погребан в основания от него манастир „Св. Пантелеймон“ в Охрид.', read: 'Пространно житие на св. Климент Охридски; св. Климент Охридски, „Поучителни слова“' },
  { id: 'b091', cat: 'Църковна история', title: 'Охридската архиепископия', text: 'След падането на Първото българско царство под византийска власт през 1018 г. император Василий II не премахнал Българската църква. Той я понижил в ранг на Охридска архиепископия, но ѝ запазил автокефалията и епархиите. С времето в нея все повече навлизало гръцко духовенство. Архиепископията просъществувала векове, докато не била премахната от османските власти през 1767 г. Тя остава символ на приемствеността на българската църковна традиция.', read: 'Теофилакт Охридски, „Житие на св. Климент“; история на Охридската архиепископия' },
  { id: 'b092', cat: 'Християнски живот', title: 'Уважение към противника', text: 'В бойните спортове противникът не е враг, а партньор, без когото няма състезание. Християнинът вижда в него образа Божий, независимо от провокациите преди мача. Уважението се показва в честната игра, в спазването на правилата, в думите преди и след боя. Унижаването на победен противник е проява на гордост, която отдалечава от Бога. Ръкостискането и прегръдката след битката могат да бъдат малко свидетелство за Христос.', read: 'Римл. 12:10; Фил. 2:3–4' },
  { id: 'b093', cat: 'Духовен живот', title: 'Лествицата – въведение', text: 'Книгата „Лествица“ на св. Йоан Синайски описва духовния живот като стълба с тридесет стъпала, по образа на стълбата, която видял патриарх Яков. Започва с отказа от света и завършва с вярата, надеждата и любовта. Между тях са описани страстите и добродетелите с изключителна точност и практичност. Макар да е писана за монаси, тя е полезна и за миряни, ако се чете с разсъждение. Чети по малко, като си задаваш въпроса: „Как това се отнася до моя живот днес?“.', read: 'Бит. 28:10–17; св. Йоан Лествичник, „Лествица“ – встъпителни слова' },
  { id: 'b094', cat: 'Светите отци и светии', title: 'Св. Наум Охридски', text: 'Свети Наум е от най-близките ученици на Кирил и Методий. След Моравия пристигнал в България и работил в Плиска и Преслав за създаването на славянската книжнина. По-късно заменил св. Климент в Охрид, когато Климент станал епископ. Основал манастир на брега на Охридското езеро, където прекарал последните си години и починал през 910 г. Почитан е като чудотворец и лечител, особено на душевни болести.', read: 'Житие на св. Наум Охридски; Мат. 10:8' },
  { id: 'b095', cat: 'Църковна история', title: 'Покръстването на Русия', text: 'През 988 г. киевският княз Владимир приел християнството от Византия и покръстил народа си в река Днепър. Според летописа пратениците му, присъствали на Литургия в Константинопол, казали: „Не знаехме дали сме на небето или на земята“. Важна роля изиграла и славянската книжнина, създадена в България, която стигнала до Русия. Свети Владимир и баба му св. Олга са почитани като равноапостолни. Това показва как красотата на богослужението може да бъде мисионерство.', read: '„Повест за отминалите години“ (летопис); Пс. 47:9' },
  { id: 'b096', cat: 'Християнски живот', title: 'Истинността', text: 'Христос нарича дявола „баща на лъжата“, а Себе Си – „Истината“. Лъжата, дори малка и „безобидна“, разрушава доверието и затъмнява съвестта. Християнинът казва „да“, когато е да, и „не“, когато е не, без да прибягва до клетви и уловки. Истинността включва и честност към себе си – да не се самозаблуждаваш за собствените си слабости. Говори истината с любов: не всяка истина трябва да се изрича навсякъде, но никога не лъжи.', read: 'Мат. 5:37; Еф. 4:25' },
  { id: 'b097', cat: 'Духовен живот', title: 'Лествица: първите стъпала', text: 'Първите три стъпала на „Лествицата“ говорят за отричането от света, безпристрастието и странничеството. Отричането не означава омраза към творението, а отказ от суетата и греховните привързаности. Св. Йоан казва, че който започва, трябва да го прави с усърдие, защото началото определя пътя. За мирянина това е решението Христос да бъде на първо място – преди кариерата, славата и удобствата. Помисли кое в живота ти най-силно те дърпа назад и го постави пред Бога.', read: 'Лука 9:62; св. Йоан Лествичник, „Лествица“, Слова 1–3' },
  { id: 'b098', cat: 'Светите отци и светии', title: 'Светите Седмочисленици', text: 'Седмочислениците са седемте светители, които Църквата почита заедно: Кирил и Методий и техните ученици Климент, Наум, Горазд, Сава и Ангеларий. Те са носители на славянската писменост и книжнина, донесли словото Божие на славянските народи. Църквата ги чества на 27 юли. Иконата на Седмочислениците е символ на единството в общото дело. Те ни напомнят, че вярата се предава от поколение на поколение чрез учители и ученици.', read: 'Житие на св. Климент Охридски; 2 Тим. 2:2' },
  { id: 'b099', cat: 'Църковна история', title: 'Великата схизма от 1054 г.', text: 'През 1054 г. папският легат кардинал Хумберт оставил в „Св. София“ в Константинопол була с отлъчване на патриарх Михаил Керуларий, а той отвърнал със свое отлъчване. Това е символичната дата на разделението между Изтока и Запада, макар отчуждението да расте векове преди и след това. Главни причини са претенциите на римския папа за власт над цялата Църква и добавката Филиокве в Символа на вярата. Различия имало и в практиката, например употребата на безквасен хляб. Взаимните анатеми от 1054 г. са вдигнати през 1965 г., но единството в Евхаристията не е възстановено.', read: 'Йоан 17:20–23; история на Великата схизма' },
  { id: 'b100', cat: 'Християнски живот', title: 'Гордостта при победата', text: 'Победата е изпитание не по-малко от загубата. Тя може да напомпа егото и да накара човека да повярва, че всичко е постигнал сам. Добре е да благодариш на Бога и на хората, които са ти помогнали – треньори, партньори, семейство. Не използвай победата, за да унижиш другите или да се превъзнасяш в медиите. Апостол Павел пита: „Какво имаш, което да не си получил?“.', read: '1 Кор. 4:7; Притч. 16:18' },
  { id: 'b101', cat: 'Духовен живот', title: 'Лествица: непаметозлобието', text: 'В девето слово на „Лествицата“ св. Йоан пише за злопаметството – помненето на злото. Той го описва като ръжда на душата и червей на ума, който отравя молитвата. Злопаметният човек не може да се моли истински, защото Господнята молитва го осъжда. Лекарството е да се молиш за обидилия те и да говориш добро за него. Св. Йоан казва, че ако не можеш да изкорениш злопаметството веднага, поне да се смириш пред Бога за това.', read: 'Мат. 5:23–24; св. Йоан Лествичник, „Лествица“, Слово 9' },
  { id: 'b102', cat: 'Светите отци и светии', title: 'Св. Иван Рилски', text: 'Свети Иван Рилски (IX–X в.) е най-почитаният български светец и небесен покровител на българския народ. Отказал се от света, той живял като отшелник в Рила планина в пещера и хралупа на дърво. Слухът за светостта му привлякъл ученици, от които се оформил Рилският манастир. Преданието разказва, че цар Петър пожелал да го види, но светецът смирено отказал среща. Преди смъртта си оставил на учениците си Завет за любов, единство и нестяжание.', read: 'Св. Иван Рилски, „Завет“; св. Евтимий Търновски, „Житие на св. Иван Рилски“' },
  { id: 'b103', cat: 'Църковна история', title: 'Кръстоносните походи', text: 'От края на XI век западни рицари тръгнали в походи към Светите земи с цел да освободят Йерусалим от мюсюлманите. Походите съчетавали искрено благочестие с жажда за земи, плячка и слава. Те засилили отчуждението между Изтока и Запада, защото кръстоносците често се отнасяли към православните като към чужди. В Антиохия и Йерусалим поставяли латински патриарси на мястото на православните. За Православието свещената война с обещание за опрощаване на грехове е чужда идея.', read: 'История на Кръстоносните походи; Мат. 26:52' },
  { id: 'b104', cat: 'Християнски живот', title: 'Социалните мрежи и вниманието', text: 'Социалните мрежи са създадени така, че да откраднат колкото се може повече от вниманието ни. Безкрайното превъртане разсейва ума, подхранва сравнението, завистта и тщеславието. Отците учат, че където е вниманието ни, там е и сърцето ни. Поставяй си граници: без телефон сутрин преди молитва и вечер преди сън, изключи ненужните известия. Използвай мрежите за добро, а не позволявай те да използват теб.', read: 'Фил. 4:8; Мат. 6:22–23' },
  { id: 'b105', cat: 'Духовен живот', title: 'Лествица: разсъждението', text: 'Двадесет и шестото слово на „Лествицата“ е посветено на разсъждението – дарът да различаваш добро от зло и Божия воля от собствените желания. Отците го смятат за една от най-важните добродетели, защото без него и подвигът може да стане вреден. При начинаещите разсъждението се проявява като познаване на себе си. То се придобива чрез смирение, послушание и съвет с опитни. Затова не предприемай сам крайни подвизи, а питай духовника.', read: '1 Йоан 4:1; св. Йоан Лествичник, „Лествица“, Слово 26' },
  { id: 'b106', cat: 'Светите отци и светии', title: 'Отшелниците на Иван Рилски', text: 'Свети Йоаким Осоговски, св. Прохор Пчински и св. Гаврил Лесновски са отшелници от XI век, почитани като следовници на подвига на св. Иван Рилски. Всеки от тях се подвизавал в планините – Осогово, Пчиня и Лесново – и около тях възникнали манастири. Те показват как примерът на един светец ражда цяла традиция на святост. Пустинята за тях е била място на молитва за целия народ. Почитат се от българи и сърби като общи светии на Балканите.', read: 'Жития на св. Йоаким Осоговски, св. Прохор Пчински и св. Гаврил Лесновски' },
  { id: 'b107', cat: 'Църковна история', title: 'Превземането на Константинопол през 1204 г.', text: 'Четвъртият кръстоносен поход вместо към Светите земи се насочил към Константинопол. През април 1204 г. кръстоносците превзели и ограбили града, осквернили храмове и отнесли безброй реликви. Създали Латинската империя и поставили латински патриарх. За православните това било най-дълбоката рана в отношенията със Запада. Скоро след това българският цар Калоян разбил латинците при Одрин през 1205 г.', read: 'Никита Хониат, „История“; история на Четвъртия кръстоносен поход' },
  { id: 'b108', cat: 'Християнски живот', title: 'Страданието', text: 'Страданието е част от живота в падналия свят и Христос не го премахва веднага, а влиза в него и го преобразява. Той Сам страда на Кръста, затова в страданието никога не сме сами. Страданието може да ожесточи човека или да го смири и да го направи по-състрадателен – изборът е наш. Отците съветват да не питаме „защо?“, а „за какво?“ и „какво да науча?“. Кажи като Йов: „Господ даде, Господ и взе – да бъде благословено името Господне“.', read: 'Йов 1:21; Римл. 8:18' },
  { id: 'b109', cat: 'Духовен живот', title: 'Лествица: безмълвие и молитва', text: 'Слова 27 и 28 на „Лествицата“ говорят за безмълвието и молитвата. Безмълвието не е само мълчание на устата, а вътрешен мир, в който умът се съсредоточава в Бога. Св. Йоан съветва молитвата да е кратка и проста, като молитвата на митаря и на благоразумния разбойник. Многословието разсейва ума, а кратката молитва го събира. Започни с едно изречение, повторено с цялото внимание.', read: 'Лука 18:13; св. Йоан Лествичник, „Лествица“, Слова 27–28' },
  { id: 'b110', cat: 'Светите отци и светии', title: 'Св. Петка Българска', text: 'Света Параскева, наричана Петка, е родена в Епиват край Цариград през XI век. Отказала се от богатството си и прекарала години в пустинята в пост и молитва. Накрая се върнала в родното си място, където починала в неизвестност. Мощите ѝ били открити по-късно и през XIII век цар Иван Асен II ги пренесъл в Търново. Българите я почитат като покровителка на жените, семейството и страдащите, а празникът ѝ е на 14 октомври.', read: 'Св. Евтимий Търновски, „Житие на св. Петка“; Притч. 31:10–31' },
  { id: 'b111', cat: 'Църковна история', title: 'Богомилството и Църквата', text: 'През X век в България се появило богомилството – дуалистично учение, което смятало материалния свят за творение на злото. Богомилите отхвърляли тайнствата, иконите, кръста и църковната йерархия. Презвитер Козма написал „Беседа против богомилите“, в която разобличава учението, но и критикува недостатъците на духовенството. През 1211 г. цар Борил свикал в Търново събор срещу ереста, а неговият Синодик е важен паметник на православната вяра. Историята показва, че ересите често растат там, където Църквата е отслабнала духовно.', read: 'Презвитер Козма, „Беседа против богомилите“; Синодик на цар Борил' },
  { id: 'b112', cat: 'Християнски живот', title: 'Болестта и контузиите', text: 'За спортиста контузията може да е най-тежкото изпитание – прекъсване на плановете, болка, несигурност. Християнинът може да преживее и това с вяра: като време за молитва, четене и вътрешен растеж. Св. Паисий Светогорец казва, че болестта носи голяма полза, когато се приема с търпение и благодарност. Грижи се за лечението разумно, слушай лекарите и не бързай със завръщането от гордост. Моли се, но не само за изцеление, а и за сила да приемеш Божията воля.', read: '2 Кор. 12:7–10; Иак. 5:13–15' },
  { id: 'b113', cat: 'Духовен живот', title: 'Лествица: вяра, надежда, любов', text: 'Последното, тридесето стъпало на „Лествицата“ е посветено на вярата, надеждата и любовта. Св. Йоан казва, че любовта е най-високата от тях, защото тя е Бог. Тя е крайната цел на всички усилия, постове и молитви. Ако подвигът не прави човека по-любящ, значи е сбъркал пътя. „Лествицата“ започва със стремеж и завършва с любов – това е посоката и на нашия живот.', read: '1 Кор. 13:1–13; св. Йоан Лествичник, „Лествица“, Слово 30' },
  { id: 'b114', cat: 'Светите отци и светии', title: 'Св. Иларион Мъгленски', text: 'Свети Иларион (XII в.) бил епископ на Мъгленската епархия. Той водил ревностна борба срещу богомилите и други ереси, като ги убеждавал със слово и пример. Бил известен с милосърдието си и грижата за паството. Мощите му по-късно били пренесени в Търново от цар Калоян. Св. Евтимий Търновски написал неговото житие.', read: 'Св. Евтимий Търновски, „Житие на св. Иларион Мъгленски“; 2 Тим. 4:2–5' },
  { id: 'b115', cat: 'Църковна история', title: 'Търновската патриаршия', text: 'След възстановяването на българската държава при Асеневци Търново станало духовен център. Цар Калоян получил от Рим титла за главата на Църквата, но тази връзка не се задържала. През 1235 г. при цар Иван Асен II, със съгласието на източните патриарси, Българската църква отново била призната за патриаршия. Първият търновски патриарх бил Йоаким I. Патриаршията просъществувала до падането на Търново през 1393 г.', read: 'История на Търновската патриаршия; св. Евтимий Търновски – жития' },
  { id: 'b116', cat: 'Християнски живот', title: 'Смъртта', text: 'За християнина смъртта е враг, но враг победен – Христос е възкръснал и „със смъртта Си смъртта победи“. Смъртта не е край, а преход, разделяне на душата от тялото до общото възкресение. Затова се молим за починалите, правим панихиди и раздаваме за душата им. Страхът от смъртта е естествен, но вярата ни дава надежда, а не отчаяние. Живей така, че да можеш да застанеш пред Христос със спокойна съвест.', read: '1 Кор. 15:51–57; 1 Сол. 4:13–18' },
  { id: 'b117', cat: 'Духовен живот', title: 'Изкушенията', text: 'Изкушението само по себе си не е грях – дори Христос бе изкушаван в пустинята. То е изпитание, което разкрива и укрепва нашата вяра. Христос отблъсна изкушенията с думите на Писанието, показвайки ни пътя. Бог не допуска изкушение, по-силно от силите ни, а заедно с него дава и изход. В момент на изкушение бягай от повода, призови Името Божие и не оставай сам с помисъла.', read: 'Мат. 4:1–11; 1 Кор. 10:13' },
  { id: 'b118', cat: 'Светите отци и светии', title: 'Св. Симеон Нови Богослов', text: 'Свети Симеон (X–XI в.) бил игумен на манастира „Св. Мамант“ в Константинопол. Той говорел смело, че Бог може да бъде съзерцаван като светлина още в този живот, ако човек живее в покаяние. Наричан е „Нови Богослов“ – трети след апостол Йоан и св. Григорий. Неговите „Химни на божествената любов“ описват личната среща с Бога. Учи, че християнството не е само теория, а жив опит на благодатта.', read: 'Йоан 8:12; св. Симеон Нови Богослов, „Химни на божествената любов“' },
  { id: 'b119', cat: 'Църковна история', title: 'Исихастките спорове', text: 'През XIV век калабрийският монах Варлаам осмял атонските монаси, които твърдели, че виждат Божията светлина в молитвата. Св. Григорий Палама защитил исихастите, като разграничил Божията същност, която е непостижима, и Божиите енергии, чрез които Бог наистина се дава на човека. Събори в Константинопол през 1341, 1347 и 1351 г. потвърдили неговото учение. Тези решения са част от православното съзнание и днес. Те утвърждават, че обожението е истинско общение с Бога.', read: '2 Петр. 1:4; св. Григорий Палама, „Триади в защита на свещенобезмълвстващите“' },
  { id: 'b120', cat: 'Християнски живот', title: 'Паметта за смъртта', text: 'Отците съветват постоянно да помним смъртта – не за да живеем в страх, а за да живеем трезво. Паметта за смъртта отрезвява от гордостта, гнева и пристрастяването към вещите. Св. Йоан Лествичник казва, че тя е като хляб – най-необходима от всички храни. Боецът знае колко крехко е тялото и колко бързо може да се изгуби всичко. Питай се вечер: ако тази нощ ме призове Господ, готов ли съм?', read: 'Сир. 7:39; св. Йоан Лествичник, „Лествица“, Слово 6' },
  { id: 'b121', cat: 'Духовен живот', title: 'Благодарността', text: 'Благодарността е една от най-простите и най-силни добродетели. Апостол Павел казва: „За всичко благодарете, защото такава е Божията воля“. Неблагодарният човек вижда само това, което липсва, а благодарният – даровете, които вече има. Св. Йоан Златоуст в изгнание, болен и гонен, умира с думите „Слава на Бога за всичко“. Опитай всяка вечер да назовеш три неща, за които благодариш на Бога този ден.', read: '1 Сол. 5:16–18; Лука 17:11–19' },
  { id: 'b122', cat: 'Светите отци и светии', title: 'Св. Григорий Палама', text: 'Свети Григорий Палама (1296–1359) е монах от Света гора, който по-късно става архиепископ на Солун. Той защитил исихазма и учението, че Бог, непостижим по Своята същност, наистина се дава на човека чрез нетварните Си енергии. Светлината, видяна от апостолите на Тавор, според него не е създадено явление, а сиянието на Божеството. Църквата го чества във втората неделя на Великия пост. Учението му ни уверява, че обожението не е метафора, а реално общение с Бога.', read: 'Мат. 17:1–8; св. Григорий Палама, „Триади в защита на свещенобезмълвстващите“' },
  { id: 'b123', cat: 'Църковна история', title: 'Падането на Търново', text: 'През 1393 г., след тримесечна обсада, османците превзели Търново – столицата на Второто българско царство. Патриарх Евтимий ръководил защитата и утешавал народа. След превземането много от знатните били избити, а патриархът бил изпратен в заточение. С това Търновската патриаршия престанала да съществува, а епархиите преминали под Цариградската патриаршия. Започнали векове на робство, в които Църквата се превърнала в убежище за българската вяра и памет.', read: 'Григорий Цамблак, „Похвално слово за Евтимий“; Пс. 136' },
  { id: 'b124', cat: 'Християнски живот', title: 'Служението на бедните', text: 'Христос се отъждествява с бедните, болните, затворниците и странниците. Затова грижата за тях не е благотворителност по избор, а част от същността на християнството. Св. Йоан Златоуст казва, че ако не можеш да намериш Христос в бедния пред храма, няма да Го намериш и в Причастната чаша. Служението може да е просто: да доставиш храна, да посетиш самотен възрастен човек, да тренираш безплатно деца. Христос гледа не размера на дара, а любовта, с която е даден.', read: 'Мат. 25:34–40; Марк 12:41–44' },
  { id: 'b125', cat: 'Духовен живот', title: 'Псалмите в молитвата', text: 'Книгата Псалтир е молитвеникът на Христос, апостолите и цялата Църква. В псалмите има всичко: радост, скръб, покаяние, гняв, страх, надежда и хвала. Те ни учат да говорим с Бога честно за всичко, което преживяваме. В богослужението Псалтирът се прочита изцяло всяка седмица, а по време на Великия пост – два пъти седмично. Започни с няколко псалма, които да научиш наизуст, например 50-и (покаен) и 90-и (за закрила).', read: 'Пс. 50; Пс. 90' },
  { id: 'b126', cat: 'Светите отци и светии', title: 'Св. Патриарх Евтимий', text: 'Свети Евтимий е последният патриарх на средновековна България (от около 1375 г. до падането на Търново през 1393 г.). Той бил исихаст, ученик на св. Теодосий Търновски, и бил свързан със Света гора. Извършил книжовна реформа, за да уеднакви правописа и да направи преводите по-верни на гръцките оригинали. Написал жития на български светии, като св. Иван Рилски и св. Петка. При обсадата на Търново останал с народа си, а след това бил заточен.', read: 'Григорий Цамблак, „Похвално слово за патриарх Евтимий“; Йоан 10:11' },
  { id: 'b127', cat: 'Църковна история', title: 'Флорентинската уния', text: 'В първата половина на XV век, притисната от османците, Византия търсила помощ от Запада. На събор във Ферара и Флоренция през 1438–1439 г. била подписана уния, при която православните трябвало да приемат папската власт и Филиокве. Единствен от православните епископи св. Марк Ефески отказал да подпише. При завръщането народът и духовенството отхвърлили унията. Тази история показва, че вярата не се търгува дори срещу политическа помощ.', read: 'Св. Марк Ефески – послания срещу унията; Гал. 1:8' },
  { id: 'b128', cat: 'Християнски живот', title: 'Приятелството', text: 'Писанието казва: „Верният приятел е силна защита; който го е намерил, намерил е съкровище“. Христос нарича учениците Си приятели, защото им е открил всичко. Добрият приятел те подкрепя, но и ти казва истината, дори когато е неприятна. Внимавай с кого прекарваш времето си, защото лошите компании развалят добрите нрави. Бъди и ти такъв приятел – верен, честен и готов да се помолиш за другия.', read: 'Сир. 6:14–17; Йоан 15:13–15' },
  { id: 'b129', cat: 'Духовен живот', title: 'Подготовка за Причастие', text: 'Светото Причастие е самото Тяло и Кръв Христови, източникът на живота в Църквата. Подготовката обикновено включва пост, изповед, помирение с хората и вечерно четене на последованието за Причастие. Мярката на поста и честотата на изповедта се определят с духовника. Най-важното е сърцето: смирение, покаяние и жажда за Христос. Не се причастявай по навик, но и не стой далеч от Чашата твърде дълго под предлог, че не си достоен – никой не е достоен, но Христос зове всички.', read: '1 Кор. 11:23–29; Йоан 6:53–58' },
  { id: 'b130', cat: 'Светите отци и светии', title: 'Св. Георги Нови Софийски', text: 'Свети Георги Нови е млад златар от Кратово, който живял в София в началото на XVI век. Мюсюлмани се опитали да го убедят да се откаже от вярата си, но той твърдо изповядал Христос. През 1515 г. бил изгорен жив. Житието му е написано от свещеник Поп Пейо, негов съвременник. Той е един от първите новомъченици в България под османска власт и пример за твърдост на младите.', read: 'Поп Пейо, „Житие на св. Георги Нови Софийски“; Мат. 10:32' },
  { id: 'b131', cat: 'Църковна история', title: 'Падането на Константинопол', text: 'На 29 май 1453 г. османският султан Мехмед II превзел Константинопол след продължителна обсада. Последният византийски император Константин XI загинал, сражавайки се на стените. В последната нощ християните се молели в „Св. София“, която след това била превърната в джамия. С падането на града завършила историята на Византия, продължила повече от хиляда години. Православният свят навлязъл в нов период, в който Църквата трябвало да оцелее под чужда власт.', read: 'Георгий Сфранцис, „Хроника“; Евр. 13:14' },
  { id: 'b132', cat: 'Християнски живот', title: 'Пазене на езика', text: 'Апостол Яков казва, че езикът е малък член, но може да запали голям огън. Клеветата, подигравката, сквернословието и клюките нараняват другите и отдалечават от Бога. Христос предупреждава, че за всяка празна дума ще дадем отговор. В спорта, в съблекалнята и в интернет често е прието грубото слово – християнинът може да е различен. Преди да кажеш нещо, питай се: истина ли е, нужно ли е, добро ли е?', read: 'Иак. 3:1–12; Мат. 12:36–37' },
  { id: 'b133', cat: 'Духовен живот', title: 'Участие в Литургията', text: 'Божествената литургия е центърът на християнския живот – там се събира Църквата и се принася Евхаристията. Тя не е представление, което гледаме, а обща служба, в която участваме с молитва, пеене и Причастие. Добре е да идваш навреме, да следиш текста и да знаеш смисъла на главните моменти. Възгласът „Горе да имаме сърцата си“ е призив да оставим всичко земно. Неделната Литургия трябва да бъде неизменна част от седмицата ти, както тренировката.', read: 'Деян. 2:42; св. Николай Кавасила, „Тълкувание на Божествената литургия“' },
  { id: 'b134', cat: 'Светите отци и светии', title: 'Св. Александър Невски', text: 'Свети Александър Невски (XIII в.) е руски княз и пълководец. Той победил шведите на река Нева и тевтонските рицари на Чудското езеро през 1242 г. В същото време проявил мъдрост, като предпочел да търпи татарската власт, за да спаси народа си и вярата му. Преди смъртта си приел монашество. Катедралата в София носи неговото име в памет на руските воини, загинали за освобождението на България.', read: 'Житие на св. Александър Невски; Йоан 15:13' },
  { id: 'b135', cat: 'Църковна история', title: 'Църквата под османска власт', text: 'В Османската империя православните били организирани като общност (Рум милет), подчинена на Цариградския патриарх. Християните плащали по-високи данъци, нямали право да носят оръжие и били ограничавани в строенето на храмове. Имало и „кръвен данък“ – девширме, при който момчета били отнемани и ислямизирани. Въпреки това вярата се пазела в семействата, в селските църкви и манастирите. Мнозина предпочели мъченичество пред отричане от Христос.', read: 'Паисий Хилендарски, „История славянобългарска“; Евр. 11:36–38' },
  { id: 'b136', cat: 'Християнски живот', title: 'Неосъждането', text: 'Христос казва: „Не съдете, за да не бъдете съдени“. Отците учат, че не можем да знаем сърцето на другия, нито покаянието му, нито какво е преживял. Осъждането идва от гордостта и прави човека слеп за собствените му грехове. Един пустинен отец отказал да съди брат, носейки на гърба си торба с пясък – „греховете ми текат зад мен, а аз съм дошъл да съдя чуждите“. Различавай: може да отхвърлиш греха, но остави човека на Божия съд.', read: 'Мат. 7:1–5; „Отечник“ – авва Мойсей' },
  { id: 'b137', cat: 'Духовен живот', title: 'Кръстното знамение', text: 'Кръстното знамение е кратка изповед на вярата и молитва с тялото. В Православието се прекръстваме със събрани три пръста (за Света Троица) и два свити към дланта (за двете природи на Христос). Докосваме челото, гърдите, дясното и лявото рамо – за да осветим ума, сърцето и силите си. Кръстът е оръжие срещу злото и знак на принадлежност към Христос. Прекръствай се бавно и съзнателно – преди хранене, преди път, преди тренировка и мач.', read: '1 Кор. 1:18; Гал. 6:14' },
  { id: 'b138', cat: 'Светите отци и светии', title: 'Св. Паисий Величковски', text: 'Свети Паисий Величковски (1722–1794) е роден в Полтава и още млад тръгнал по пътя на монашеството. Подвизавал се на Света гора, а после ръководил големи манастири в Молдова, сред които Нямц. Събрал и превел на църковнославянски текстовете на отците за умната молитва, издадени като славянското „Добротолюбие“. Чрез учениците му исихастката традиция се възродила в Русия и дала плод в старците на Оптина пустиня. Той показва колко важно е отеческото предание да се предава живо.', read: '„Добротолюбие“; житие на св. Паисий Величковски' },
  { id: 'b139', cat: 'Църковна история', title: 'Новомъчениците', text: 'Под османска власт много християни пострадали за вярата си, защото отказали да приемат исляма или се върнали към Христос, след като били насилствено ислямизирани. Те са наречени новомъченици. Сред българските са св. Георги Нови Софийски, св. Никола Софийски, св. Злата Мъгленска и мнозина други. Често това били обикновени хора – занаятчии, млади момичета, селяни. Техният пример ни напомня, че вярата се изповядва не само с думи, но и с живота.', read: 'Св. Никодим Светогорец, „Нов мартирологий“; Откр. 7:13–14' },
  { id: 'b140', cat: 'Християнски живот', title: 'Завистта', text: 'Завистта е тъга от чуждото добро – от успеха, таланта или щастието на другия. Тя е първият грях след грехопадението: Каин убил Авел от завист. В спорта лесно се завижда на по-успешните, по-известните или по-добре платените. Лекарството е благодарността за собствените дарове и радостта с другия, сякаш неговият успех е твой. Моли се конкретно за човека, на когото завиждаш – това бързо изцелява сърцето.', read: 'Бит. 4:3–8; Римл. 12:15' },
  { id: 'b141', cat: 'Духовен живот', title: 'Иконите и домашният кът', text: 'Православният дом има иконен кът, обикновено на източната стена, с икона на Христос, на Богородица и на светията покровител. Там се пали кандило и се събира семейството за молитва. Иконата е прозорец към небето – чрез образа почитаме изобразения. Тя напомня, че Бог и светиите са близо и че домът ни принадлежи на Христос. Дори скромен кът с една икона и кандило може да промени атмосферата в дома.', read: 'Изх. 25:18–22; св. Йоан Дамаскин, „Три слова в защита на иконите“' },
  { id: 'b142', cat: 'Светите отци и светии', title: 'Св. Серафим Саровски', text: 'Свети Серафим Саровски (XVIII–XIX в.) е един от най-обичаните руски светии. Години живял в гората като отшелник и, според житието, хиляда нощи се молил на камък. След това приемал хиляди посетители, които поздравявал с „Радост моя, Христос воскресе!“. В известния разговор с Мотовилов казва, че целта на християнския живот е придобиването на Светия Дух. Неговият съвет е: „Придобий мирен дух и хиляди около теб ще се спасят“.', read: 'Разговор на св. Серафим Саровски с Н. Мотовилов; Гал. 5:22' },
  { id: 'b143', cat: 'Църковна история', title: 'Манастирите и килийните училища', text: 'През османския период манастирите се превърнали в огнища на вярата, книжнината и националната памет. В тях се преписвали книги, пазели се реликви и се приютявали пътници и преследвани. Към манастирите и църквите се развили килийни училища, където децата учели да четат по Псалтира и Часослова. Таксидиоти – монаси, които обикаляли селата – събирали помощи и поддържали връзката с народа. Без тях българската идентичност трудно би оцеляла.', read: 'История на килийните училища; Паисий Хилендарски, „История славянобългарска“' },
  { id: 'b144', cat: 'Християнски живот', title: 'Пристрастяванията', text: 'Пристрастяването – към алкохол, наркотици, стимуланти, хазарт или екран – е робство, при което желанието владее волята. Църквата вижда в него страст, която трябва да се лекува с благодат и с практическа помощ. Апостол Павел казва: „Всичко ми е позволено, но аз няма да се оставя нищо да ме владее“. В спорта съществува и изкушението на забранените вещества, което съчетава измама с вреда за тялото. Не се срамувай да потърсиш помощ – от духовник, лекар или група за подкрепа.', read: '1 Кор. 6:12; Еф. 5:18' },
  { id: 'b145', cat: 'Духовен живот', title: 'Четенето на Писанието', text: 'Свещеното Писание е Божие слово, написано от хора, вдъхновени от Светия Дух. Православните го четат в Църквата и с Църквата – в светлината на тълкуванията на светите отци. Преди четене се помоли Бог да отвори ума ти, както отвори ума на учениците по пътя за Емаус. Започни с Евангелията и чети всеки ден по малко, например по една глава. Не търси информация, а среща: какво ми казва Христос днес чрез тези думи?', read: 'Лука 24:27–32; 2 Тим. 3:14–17' },
  { id: 'b146', cat: 'Светите отци и светии', title: 'Св. Паисий Хилендарски', text: 'Свети Паисий (1722–1773) е бил монах в Хилендарския манастир на Света гора. Наскърбен от това, че българите забравят своя род и език, той събрал материали и през 1762 г. завършил „История славянобългарска“. В нея остро укорява онези, които се срамуват да се нарекат българи, и припомня славното минало на народа и неговите светии. Книгата му се преписвала и разпространявала из българските земи и пробудила националното съзнание. Българската църква го канонизира през 1962 г.', read: 'Паисий Хилендарски, „История славянобългарска“; Пс. 136:5–6' },
  { id: 'b147', cat: 'Църковна история', title: 'Света гора Атон', text: 'Атон е полуостров в Северна Гърция, който от векове е посветен изцяло на монашеския живот. През 963 г. св. Атанасий Атонски основал Великата лавра с подкрепата на император Никифор Фока. Днес там има двадесет манастира, сред които руски, сръбски и българският Зограф. Светогорците го наричат „Градината на Богородица“ и по традиция жени не се допускат там. Атон е пазител на исихастката традиция и много поклонници търсят там духовно обновление.', read: 'Житие на св. Атанасий Атонски; „Добротолюбие“' },
  { id: 'b148', cat: 'Християнски живот', title: 'Неделята и почивката', text: 'Бог благословил седмия ден и го осветил, а християните празнуват неделята – деня на Възкресението. Неделята не е просто почивен ден, а ден за Литургия, семейство, добри дела и духовно четене. Почивката е част от Божия порядък: и тялото, и душата се нуждаят от възстановяване. Спортистите знаят, че без почивка няма прогрес – същото важи и за душата. Пази неделната сутрин за Църквата, дори когато графикът е натоварен.', read: 'Изх. 20:8–11; Марк 2:27' },
  { id: 'b149', cat: 'Духовен живот', title: 'Безстрастието', text: 'Безстрастието в отеческото разбиране не е безчувственост, а свобода от страстите. Силите на душата не се унищожават, а се насочват към Бога и доброто. Безстрастният човек обича всички еднакво, не се поддава на обиди и похвали и вижда нещата ясно. Отците смятат безстрастието за плод на дълъг подвиг и благодат, а не на техника. То е като спокойствието на опитния боец – резултат от години труд.', read: 'Гал. 5:24; св. Йоан Лествичник, „Лествица“, Слово 29' },
  { id: 'b150', cat: 'Светите отци и светии', title: 'Св. Софроний Врачански', text: 'Свети Софроний Врачански (1739–1813), със светско име Стойко Владиславов, бил свещеник в Котел, а по-късно епископ на Враца. Той преписал „История славянобългарска“ на Паисий и продължил неговото дело. През 1806 г. издал „Неделник“ – първата печатна книга на новобългарски език, сборник с поучения за неделите и празниците. Автобиографията му „Житие и страдания грешнаго Софрония“ описва тежкия живот на българите под робство. Българската църква го прославя като светия.', read: 'Софроний Врачански, „Житие и страдания грешнаго Софрония“; Йоан 10:11' },
  { id: 'b151', cat: 'Църковна история', title: 'Зограф и Зографските мъченици', text: 'Зографският манастир на Света гора е българският светогорски манастир, посветен на св. Георги. Името му – „живописец“ – идва от предание за чудотворна икона на светеца. В XIII век, по времето на опитите за уния с Рим, двадесет и шестима монаси от Зограф отказали да приемат унията и били изгорени в манастирската кула. Те се почитат като Зографски мъченици. Манастирът е пазил през вековете български ръкописи и книжнина.', read: 'Житие на Зографските мъченици; Евр. 12:1–2' },
  { id: 'b152', cat: 'Християнски живот', title: 'Свидетелството за вярата', text: 'Христос казва, че който Го изповяда пред хората, и Той ще го изповяда пред Отца Си. Свидетелството не означава да проповядваш агресивно, а да не се срамуваш от вярата. Най-силно свидетелство е животът – честността, спокойствието, уважението към противника. Човек с публичност, като спортист, има особена възможност да покаже, че вярата и силата вървят заедно. Бъди готов кротко да отговориш на всеки, който пита за надеждата ти.', read: '1 Петр. 3:15; Мат. 5:14–16' },
  { id: 'b153', cat: 'Духовен живот', title: 'Обожението', text: 'Целта на християнския живот според Православието е обожението (теозис) – съединение с Бога по благодат. Апостол Петър казва, че сме призвани да станем „причастници на божественото естество“. Това не значи да станем Бог по същност, а да бъдем изпълнени с Неговия живот, както желязото в огъня се нагорещява. Пътят е чрез Църквата, тайнствата, молитвата и заповедите. Обожението започва още тук, в малките победи над себе си, и продължава вечно.', read: '2 Петр. 1:3–4; св. Атанасий Велики, „За въплъщението на Словото“, 54' },
  { id: 'b154', cat: 'Светите отци и светии', title: 'Баташките мъченици', text: 'По време на Априлското въстание през 1876 г. селото Батак било нападнато от башибозуци. Стотици жители, сред тях жени и деца, се укрили в църквата „Св. Неделя“, където били избити. Мнозина загинали, отказвайки да се отрекат от Христос. През 2011 г. Българската православна църква ги прослави като светии. Църквата в Батак и днес носи следи от трагедията и е място за поклонение и молитва.', read: 'Откр. 6:9–11; Мат. 10:28' },
  { id: 'b155', cat: 'Църковна история', title: 'Рилският манастир', text: 'Рилският манастир е основан през X век от учениците на св. Иван Рилски близо до мястото на неговия подвиг. През вековете той е бил духовен и културен център и пазител на мощите на светеца. Кулата на Хрельо от XIV век е най-старата запазена сграда. След пожар в началото на XIX век манастирът бил възстановен в днешния си вид с помощта на дарения от целия народ. Той е символ на българското Православие и е под закрилата на ЮНЕСКО.', read: 'Св. Иван Рилски, „Завет“; история на Рилската света обител' },
  { id: 'b156', cat: 'Християнски живот', title: 'Страхът', text: 'Страхът е естествена реакция, но може да стане господар, който парализира и води към грях. Най-често в Писанието Бог казва: „Не бой се“. Има и добър страх – страхът Божий, който е благоговение и нежелание да огорчим Бога. Страхът пред мача, пред болестта или бъдещето може да се предаде в молитва. Колкото повече расте доверието в Бога, толкова повече „съвършената любов изгонва страха“.', read: '1 Йоан 4:18; Пс. 26:1' },
  { id: 'b157', cat: 'Духовен живот', title: 'Вяра и съмнение', text: 'Вярата не е само убеждение на ума, а доверие в Бога, което обхваща целия живот. Съмненията идват при всеки, дори при апостолите – Тома не повярвал, докато не видял. Важно е да не ги криеш, а да ги принесеш на Бога и да говориш с духовника. Бащата на болното момче казал на Христос: „Вярвам, Господи, помогни на неверието ми“ – това е честна молитва. Вярата расте чрез участие в живота на Църквата, а не само чрез разсъждения.', read: 'Марк 9:24; Йоан 20:24–29' },
  { id: 'b158', cat: 'Светите отци и светии', title: 'Св. Теодор Ушаков', text: 'Свети Теодор Ушаков (1745–1817) е руски адмирал, който според преданието не е загубил нито една морска битка. Бил дълбоко вярващ, молел се преди всяко сражение и се грижел за моряците си като баща. Проявявал милост към пленниците и не допускал насилие над мирното население. В последните си години живеел скромно, раздавал на бедните и прекарвал много време в храма. Руската църква го прослави като светия през 2001 г.', read: 'Житие на св. Теодор Ушаков; Пс. 106:23–30' },
  { id: 'b159', cat: 'Църковна история', title: 'Бачковският манастир', text: 'Бачковският манастир е основан през 1083 г. от византийския военачалник от грузински произход Григорий Бакуриани. Той е един от най-големите и най-старите манастири в България. В неговата костница са запазени ценни стенописи, а в манастира се пази почитана чудотворна икона на Богородица. През вековете той е бил място за молитва на поклонници от различни народи. Посещението на подобни места е добра възможност за духовна почивка и обновление.', read: 'Типикът на Григорий Бакуриани; история на Бачковската обител' },
  { id: 'b160', cat: 'Християнски живот', title: 'Поражението', text: 'Всеки боец губи – въпросът е как. Поражението може да смири и да научи, или да ожесточи и да доведе до отчаяние. Христос изглеждаше победен на Кръста, но от поражението се роди Възкресението. Дори на светиите им се случвало да паднат, но те ставали отново. Отците казват: „Падна ли – стани; падна пак – пак стани“.', read: 'Мих. 7:8; Притч. 24:16' },
  { id: 'b161', cat: 'Духовен живот', title: 'Надеждата', text: 'Надеждата е една от трите богословски добродетели заедно с вярата и любовта. Тя не е оптимизъм, а увереност, че Бог е верен на обещанията Си, дори когато обстоятелствата изглеждат безнадеждни. Противоположността ѝ е отчаянието, което отците смятат за една от най-опасните примки. Юда и Петър съгрешили тежко, но Петър се покаял с надежда, а Юда се отчаял. Никога не губи надежда в Божията милост – тя е по-голяма от всеки грях.', read: 'Римл. 5:1–5; Евр. 6:18–19' },
  { id: 'b162', cat: 'Светите отци и светии', title: 'Св. Йоан Кронщадски', text: 'Свети Йоан Кронщадски (1829–1908) е бил енорийски свещеник в Кронщад край Санкт Петербург в продължение на десетилетия. Той служил всеки ден Литургия, призовавал към често Причастие и грижа за бедните. Създал „Дом на трудолюбието“, където бедните получавали работа, храна и подслон. Хиляди хора идвали при него за молитва и съвет. Дневникът му „Моят живот в Христа“ е класика на православната духовност.', read: 'Св. Йоан Кронщадски, „Моят живот в Христа“; Иак. 2:14–17' },
  { id: 'b163', cat: 'Църковна история', title: 'Великденската акция от 1860 г.', text: 'През XIX век българите водели борба за собствена църква, независима от гръцкото духовенство на Цариградската патриаршия. На Великден 1860 г. в българската църква в Цариград епископ Иларион Макариополски не споменал името на патриарха по време на службата. Това бил символичен акт на отказ от подчинение, подкрепен от народа. Последвали години на преговори и напрежение с Патриаршията и Високата порта. Тази акция е началото на пътя към Българската екзархия.', read: 'История на борбата за църковна независимост; Йоан 17:21' },
  { id: 'b164', cat: 'Християнски живот', title: 'Успехът', text: 'Успехът е благословение, но и отговорност и изпитание. Той може да донесе пари, слава и влияние, които лесно водят към гордост и разсейване. Христос казва: „Каква полза за човека, ако спечели целия свят, а повреди душата си?“. Използвай успеха, за да помагаш на другите и да свидетелстваш за Бога. Помни, че всяка победа е дар, а славата е преходна – истинският успех е да си верен на Христос.', read: 'Марк 8:36; Пс. 113:9' },
  { id: 'b165', cat: 'Духовен живот', title: 'Любовта към Бога и ближния', text: 'Христос обобщава целия закон в две заповеди: да обичаме Бога с цялото си сърце и ближния си като себе си. Любовта към Бога се проверява в любовта към ближния, защото „който не обича брата си, когото е видял, как може да обича Бога, Когото не е видял?“. Любовта не е само чувство, а действие – търпение, служение, прошка. Св. Доротей сравнява Бога с центъра на кръг, а хората с точки по радиусите: колкото по-близо сме до Бога, толкова по-близо сме един до друг. Всеки ден търси една конкретна възможност да покажеш любов.', read: 'Мат. 22:37–40; 1 Йоан 4:20–21' },
  { id: 'b166', cat: 'Светите отци и светии', title: 'Св. Нектарий Егински', text: 'Свети Нектарий (1846–1920) е бил митрополит в Египет, но заради интриги и клевети бил отстранен без съд. Той не се защитавал, а смирено приел несправедливостта и живял в бедност. По-късно ръководил духовна семинария в Атина и основал женски манастир на остров Егина. Бил известен с кротостта и смирението си, а след смъртта му станали много чудеса. Канонизиран е през 1961 г. и е почитан като чудотворец и лечител.', read: 'Житие на св. Нектарий Егински; Мат. 5:10–12' },
  { id: 'b167', cat: 'Църковна история', title: 'Ферманът от 1870 г.', text: 'През 1870 г. султан Абдул Азиз издал ферман за учредяване на Българска екзархия. Тя обхващала епархиите с преобладаващо българско население, като се предвиждало и други да се присъединят чрез допитване. Първият екзарх Антим I бил избран през 1872 г. Цариградската патриаршия обявила Екзархията за схизматична същата година, а схизмата била вдигната едва през 1945 г. Фирманът е важен момент и за признаването на българите като отделен народ в империята.', read: 'Текст на султанския ферман от 1870 г.; история на Българската екзархия' },
  { id: 'b168', cat: 'Християнски живот', title: 'Любовта към родината', text: 'Любовта към родината е естествена и добра, когато е подчинена на любовта към Бога. Светиите са се молили и жертвали за народа си, като св. Иван Рилски, св. Паисий и св. Софроний. Християнинът служи на родината с честен труд, спазване на законите и грижа за ближните. Опасно е, когато любовта към своите се превърне в омраза към другите. В Христос „няма ни елин, ни юдеин“ – всички сме призвани в едно Тяло.', read: 'Гал. 3:28; Римл. 9:1–3' },
  { id: 'b169', cat: 'Духовен живот', title: 'Молитвата за другите', text: 'Молитвата за другите е израз на любовта и на единството ни в Църквата. Апостол Павел постоянно моли християните да се молят един за друг, а Яков казва, че усилената молитва на праведника може много. Можеш да имаш кратък списък с имена – семейство, приятели, съотборници, болни, починали – и да ги споменаваш всеки ден. Подаването на имена за Литургията е особено силна молитва, защото те се поменават при Евхаристията. Не забравяй да се молиш и за онези, които не обичаш.', read: 'Иак. 5:16; 1 Тим. 2:1–4' },
  { id: 'b170', cat: 'Светите отци и светии', title: 'Св. Силуан Атонски', text: 'Свети Силуан (1866–1938) бил руски селянин, силен и буен младеж, който веднъж в сбиване едва не убил човек. Покаял се, отишъл на Света гора и станал монах в руския манастир „Св. Пантелеймон“. След години на тежка духовна борба получил от Христос думите: „Дръж ума си в ада и не се отчайвай“. Той учи, че мярката на християнството е любовта към враговете. Неговият ученик архимандрит Софроний (Сахаров) описва живота и учението му в книгата „Старец Силуан“.', read: 'Архим. Софроний (Сахаров), „Старец Силуан“; Мат. 5:44' },
  { id: 'b171', cat: 'Църковна история', title: 'Българската екзархия', text: 'След фермана от 1870 г. Българската екзархия обединила българите в Османската империя около собствена църква. Първият екзарх Антим I бил кратко на поста, а екзарх Йосиф I го ръководил почти тридесет години. Екзархията изграждала училища, храмове и църковни общини в Македония и Тракия. Тя е изиграла огромна роля за запазването на българската идентичност. След Освобождението седалището ѝ останало в Цариград до 1913 г., когато било преместено в София.', read: 'История на Българската екзархия; дневниците на екзарх Йосиф I' },
  { id: 'b172', cat: 'Християнски живот', title: 'Властта и законът', text: 'Апостол Павел учи, че властите са допуснати от Бога и християнинът трябва да спазва законите и да плаща данъците си. Това включва и честност пред държавата, работодателя и спортните правила. Но когато властта заповядва да се отречем от Бога или да извършим явно зло, важи думата на апостолите: „Трябва да се покоряваме повече Богу, нежели на човеците“. Християнинът се моли за управляващите, а не ги проклина. Гражданската отговорност е част от любовта към ближния.', read: 'Римл. 13:1–7; Деян. 5:29' },
  { id: 'b173', cat: 'Духовен живот', title: 'Ангелът пазител', text: 'Църквата учи, че всеки кръстен човек има ангел пазител, даден от Бога. Христос казва за децата, че ангелите им винаги виждат лицето на Небесния Отец. Ангелът пази, вдъхновява за доброто и се моли за нас, но не отнема свободната ни воля. В молитвеника има молитви към ангела пазител, които се четат сутрин и вечер. Добре е да му благодариш за закрилата, особено след опасност или трудна битка.', read: 'Мат. 18:10; Пс. 90:11–12' },
  { id: 'b174', cat: 'Светите отци и светии', title: 'Св. Серафим Софийски', text: 'Свети Серафим (Соболев) (1881–1950) бил руски архиепископ, който след революцията емигрирал и от 1921 г. живял в София. Служил в руската църква „Св. Николай“ и бил духовен наставник на много българи. Бил ревностен защитник на православната вяра, автор на богословски трудове, човек на молитва и строг подвиг. Хората идвали при него за съвет и утеха, а и до днес идват на гроба му в криптата на руската църква. Българската църква го прослави като светия през 2016 г.', read: 'Житие на св. Серафим Софийски; Йоан 21:15–17' },
  { id: 'b175', cat: 'Църковна история', title: 'Църквата и спасяването на евреите', text: 'През 1943 г. Българската православна църква се противопостави на депортирането на българските евреи. Митрополит Стефан Софийски и митрополит Кирил Пловдивски открито застанаха в тяхна защита. Митрополит Кирил заявил, че ще легне на релсите пред влаковете, ако е нужно. Заедно с общественици и депутати Църквата допринесла евреите от старите предели на България да не бъдат изпратени в лагерите на смъртта. Тази история показва как Църквата може да бъде съвест на народа.', read: 'Лука 10:25–37; Притч. 24:11' },
  { id: 'b176', cat: 'Християнски живот', title: 'Наставничеството', text: 'В живота, както и в спорта, всеки има нужда от наставник и всеки е призван да бъде наставник за някого. Апостол Павел учи Тимотей и му заръчва да предаде наученото на верни хора, които да учат и други. Добрият наставник дава пример, а не само съвети, и не прави ученика зависим от себе си. Като треньор или по-опитен съотборник имаш влияние върху по-младите – използвай го, за да ги насърчаваш към доброто. Моли се за тези, които те учат, и за тези, които ти учиш.', read: '2 Тим. 2:1–2; Тит 2:6–8' },
  { id: 'b177', cat: 'Духовен живот', title: 'Книгата „Добротолюбие“', text: '„Добротолюбие“ е сборник с текстове на светите отци за молитвата, трезвението и духовната борба. Съставен е от св. Никодим Светогорец и св. Макарий Коринтски и е издаден на гръцки през 1782 г. Славянският превод на св. Паисий Величковски, а после руският на св. Теофан Затворник, разпространили тази мъдрост широко. Книгата е предназначена главно за монаси, но много текстове са полезни и за миряни. Добре е да се чете постепенно и с благословението на духовник.', read: '„Добротолюбие“, т. 1 – св. Антоний Велики; св. Исихий Презвитер' },
  { id: 'b178', cat: 'Светите отци и светии', title: 'Св. Паисий Светогорец', text: 'Свети Паисий (1924–1994) е роден в Кападокия малко преди преселването на семейството му в Гърция. Служил като радист в армията по време на гражданската война и после станал монах на Света гора. Хиляди хора идвали в килията му за съвет и утеха. Учението му е просто и дълбоко: добрият помисъл, благородството, жертвата и молитвата за света. Канонизиран е през 2015 г. и словата му са преведени и на български.', read: 'Св. Паисий Светогорец, „Слова“, т. 1 „С болка и любов за съвременния човек“; Римл. 12:21' },
  { id: 'b179', cat: 'Църковна история', title: 'Възстановяването на патриаршията', text: 'След 1944 г. комунистическата власт започнала да ограничава Църквата: свещеници били преследвани, религиозното образование – изтласкано, а през 1948 г. екзарх Стефан бил отстранен. Въпреки натиска, на 10 май 1953 г. църковен събор възстановил Българската патриаршия. За патриарх бил избран митрополит Кирил Пловдивски. През 1961 г. Цариградската патриаршия признала патриаршеското достойнство на Българската църква. Така след векове Църквата отново имала патриарх, макар и в условия на несвобода.', read: 'История на Българската православна църква през XX век; Мат. 16:18' },
  { id: 'b180', cat: 'Християнски живот', title: 'Мирът в сърцето', text: 'Съвременният човек живее в постоянна тревожност – за пари, кариера, здраве и бъдеще. Христос казва: „Мир ви оставям, Моя мир ви давам; не тъй, както светът дава“. Божият мир не е отсъствие на проблеми, а спокойствие на душата, която се доверява на Бога. Той се придобива с молитва, благодарност, изповед и отказ от постоянното сравнение с другите. Когато тревогата нахлуе, кажи: „Да бъде волята Твоя“ – и направи следващата стъпка.', read: 'Йоан 14:27; Фил. 4:6–7' },
  { id: 'b181', cat: 'Духовен живот', title: 'Съвестта', text: 'Съвестта е гласът на Бога в човека, вътрешен закон, който ни показва кое е добро и кое зло. Тя може да бъде изострена чрез внимание и покаяние или затъпена чрез навика към греха. Отците съветват всяка вечер да проверяваме съвестта си: какво сме казали, мислили и направили. Св. Доротей казва, че съвестта е като извор, който се засипва, ако го пренебрегваме, затова трябва да я пазим чиста. Слушай съвестта си в малкото и тя ще те пази в голямото.', read: 'Римл. 2:14–15; авва Доротей, „Душеполезни поучения“, Поучение 3' },
  { id: 'b182', cat: 'Светите отци и светии', title: 'Св. Порфирий Кавсокаливит', text: 'Свети Порфирий (1906–1991) е роден в бедно гръцко село и още като момче отишъл на Света гора. Там получил дар на прозорливост и изцеление, а по-късно дълги години служил като свещеник в болница в Атина. Учел, че християнството е радост и любов, а не страх и мрачно усилие. Съветвал да не воюваме директно със злото, а да се обърнем с любов към Христос и тогава злото ще отстъпи. Канонизиран е през 2013 г.', read: 'Св. Порфирий Кавсокаливит, „Живот и слова“; Фил. 4:4' },
];
